"use client"

import React, {
    useMemo,
} from "react"
import {
    KeyStatusChipVariant,
} from "../enums"
import {
    AI_BALANCER_KEY_STATUS_DARK_MAP,
    AI_BALANCER_KEY_STATUS_LIGHT_MAP,
} from "../map"
import { cn } from "@heroui/react"
import { AiBalancerKeyStatus } from "@/modules/api/graphql/queries/enums/ai-balancer-key-status"

interface KeyStatusChipProps {
    /** Raw status string from GraphQL (`active` / `disabled` / `probing`). */
    status: string
    /** Translated label for the status. */
    label: string
    /** Light vs dark chip palette (defaults to dark). */
    variant?: KeyStatusChipVariant
}

/**
 * Colored status chip for one balancer API key row.
 *
 * @param props.status - Backend key lifecycle status.
 * @param props.label - Localized status label.
 * @param props.variant - Surface palette (light learn page vs dark admin).
 */
export const KeyStatusChip = ({
    status,
    label,
    variant = KeyStatusChipVariant.Dark}: KeyStatusChipProps) => {
    const visual = useMemo(
        () => {
            const map = variant === KeyStatusChipVariant.Light
                ? AI_BALANCER_KEY_STATUS_LIGHT_MAP
                : AI_BALANCER_KEY_STATUS_DARK_MAP
            return map[status]
                ?? map[AiBalancerKeyStatus.Active]
        },
        [
            status,
            variant,
        ],
    )

    const StatusIcon = visual.Icon

    return (
        <span
            className={cn("inline-flex items-center gap-2 rounded-full border px-3 py-0 text-xs font-medium", visual.chipClassName)}
        >
            <StatusIcon
                className="h-3.5 w-3.5"
            />
            {label}
        </span>
    )
}

"use client"

import React from "react"
import { ArrowLeftIcon } from "@phosphor-icons/react"
import { Button } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { Panel } from "@xyflow/react"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"

/**
 * Floating back-affordance for the full-bleed mind-map canvas — the canvas has
 * no chrome/breadcrumb of its own, so without this button a learner has no way
 * to leave except by clicking a lesson node (a forward action, not back).
 */
export const MindMapBackButton = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const displayId = useAppSelector((state) => state.course.displayId)

    const onPress = () => {
        if (!displayId) {
            return
        }
        router.push(pathConfig().locale(locale).course(displayId).learn().build())
    }

    return (
        <Panel className="!m-4" position="top-left">
            <Button
                isIconOnly
                variant="secondary"
                aria-label={t("mindMap.backToCourse")}
                onPress={onPress}
                className="rounded-full shadow-lg"
            >
                <ArrowLeftIcon className="size-5" />
            </Button>
        </Panel>
    )
}

"use client"

import {
    ArrowsInIcon,
    ArrowsOutIcon,
    MagnifyingGlassMinusIcon,
    MagnifyingGlassPlusIcon,
} from "@phosphor-icons/react"
import React, { type RefObject, useCallback, useEffect, useState } from "react"
import { Button } from "@heroui/react"
import { useTranslations } from "next-intl"
import { Panel, useReactFlow } from "@xyflow/react"

/** Props for {@link MindMapFullscreenButton}. */
export interface MindMapFullscreenButtonProps {
    /** The element to toggle into fullscreen (the mind-map canvas container). */
    targetRef: RefObject<HTMLElement | null>
}

/**
 * Floating zoom + fullscreen controls for the mind-map canvas.
 *
 * Sits bottom-right (where the Next.js dev badge sits): zoom in/out via React Flow and
 * toggles the browser Fullscreen API on the canvas container — no auth needed.
 * The fullscreen button icon switches between expand / collapse based on active fullscreen state.
 *
 * Must render as a child of {@link ReactFlow} so {@link useReactFlow} is available.
 *
 * @param props.targetRef - ref to the canvas container element.
 */
export const MindMapFullscreenButton = ({ targetRef }: MindMapFullscreenButtonProps) => {
    const t = useTranslations()
    const { zoomIn, zoomOut } = useReactFlow()
    const [isFullscreen, setIsFullscreen] = useState(false)

    useEffect(() => {
        const onFullscreenChange = () => {
            setIsFullscreen(document.fullscreenElement === targetRef.current)
        }

        document.addEventListener("fullscreenchange", onFullscreenChange)
        return () => document.removeEventListener("fullscreenchange", onFullscreenChange)
    }, [targetRef])

    const onPressZoomIn = useCallback(() => {
        void zoomIn({ duration: 200 })
    }, [zoomIn])

    const onPressZoomOut = useCallback(() => {
        void zoomOut({ duration: 200 })
    }, [zoomOut])

    const onPressFullscreen = useCallback(() => {
        const element = targetRef.current
        if (!element) {
            return
        }
        // toggle: exit if already fullscreen, otherwise request it on the canvas container
        if (document.fullscreenElement) {
            void document.exitFullscreen()
            return
        }
        void element.requestFullscreen?.()
    }, [targetRef])

    const fullscreenLabel = isFullscreen
        ? t("mindMap.exitFullscreen")
        : t("mindMap.fullscreen")

    return (
        <Panel className="!m-4 flex flex-col gap-2" position="bottom-right">
            <Button
                isIconOnly
                variant="secondary"
                aria-label={t("mindMap.zoomIn")}
                onPress={onPressZoomIn}
                className="rounded-full shadow-lg"
            >
                <MagnifyingGlassPlusIcon className="size-5" />
            </Button>
            <Button
                isIconOnly
                variant="secondary"
                aria-label={t("mindMap.zoomOut")}
                onPress={onPressZoomOut}
                className="rounded-full shadow-lg"
            >
                <MagnifyingGlassMinusIcon className="size-5" />
            </Button>
            <Button
                isIconOnly
                variant="secondary"
                aria-label={fullscreenLabel}
                onPress={onPressFullscreen}
                className="rounded-full shadow-lg"
            >
                {isFullscreen ? (
                    <ArrowsInIcon className="size-5" />
                ) : (
                    <ArrowsOutIcon className="size-5" />
                )}
            </Button>
        </Panel>
    )
}

"use client"

import React, { useCallback } from "react"
import { Handle, type Node, type NodeProps, Position } from "@xyflow/react"
import { cn } from "@heroui/react"
import { useRouter } from "next/navigation"
import { useLocale } from "next-intl"
import { CheckCircleIcon } from "@phosphor-icons/react"

import { GlyphMark } from "@/components/atoms/display/GlyphMark"
import { COURSE_MODULE_SLOT_NODE_TYPE, SLOT_NODE_HEIGHT, SLOT_NODE_WIDTH } from "../moduleExpansion"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"

/** React Flow node data for a `courseModuleContent` (lesson) node. */
export type CourseModuleSlotNodeData = {
    /** Parent `courseModule` node id this lesson belongs to. */
    parentModuleId: string
    /** Course mount slug — needed to build the lesson URL. */
    courseDisplayId: string
    /** Owning module id — part of the lesson URL. */
    moduleId: string
    /** Lesson (content) id this card opens. */
    contentId: string
    /** Lesson title shown on the card. */
    label: string
    /** True when the parent module sits in the left column (handle faces right, toward the module). */
    isLeft: boolean
    /** Whether the viewer has read this lesson. */
    isRead: boolean
}

/** React Flow node type for a `courseModuleContent` (lesson) node. */
export type CourseModuleSlotFlowNode = Node<CourseModuleSlotNodeData, typeof COURSE_MODULE_SLOT_NODE_TYPE>

/**
 * Real lesson card expanded beside a course module. Clicking navigates straight into
 * the lesson reader (the map is a content surface — no intermediate preview drawer).
 * Guests are bounced to the authentication modal first. A read flag marks finished lessons.
 * @param props — React Flow `NodeProps` for `courseModuleContent` nodes.
 */
export const CourseModuleSlotNode = (props: NodeProps<CourseModuleSlotFlowNode>) => {
    const { data, selected } = props
    const router = useRouter()
    const locale = useLocale()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const authentication = useAuthenticationOverlayState()

    const onOpen = useCallback(() => {
        // gate: guests cannot open the lesson — bounce them to the auth modal
        if (!authenticated) {
            authentication.open()
            return
        }
        if (!data.courseDisplayId) {
            return
        }
        router.push(
            pathConfig()
                .locale(locale)
                .course(data.courseDisplayId)
                .learn()
                .module(data.moduleId)
                .content(data.contentId)
                .build(),
        )
    }, [
        authenticated,
        authentication,
        router,
        locale,
        data.courseDisplayId,
        data.moduleId,
        data.contentId,
    ])

    return (
        <button
            type="button"
            onClick={(event) => {
                // keep the click on the card → open lesson; don't let the canvas zoom-handler also fire
                event.stopPropagation()
                onOpen()
            }}
            className={cn(
                "nodrag nopan relative flex items-center justify-center gap-2 rounded-2xl px-3 py-2 text-center",
                "border bg-background/90 text-sm font-medium text-foreground shadow-sm outline-none",
                "transition-all duration-200 hover:border-accent hover:bg-accent/5 hover:shadow-md hover:ring-2 hover:ring-accent/30",
                "focus-visible:ring-2 focus-visible:ring-accent/40",
                "dark:border-zinc-600/80 dark:bg-zinc-900/90 dark:hover:bg-accent-soft dark:hover:ring-accent/40",
                selected && "ring-2 ring-accent",
            )}
            style={{ width: SLOT_NODE_WIDTH, minHeight: SLOT_NODE_HEIGHT }}
        >
            <Handle
                isConnectable={false}
                className="!h-px !w-px !min-h-0 !min-w-0 !border-0 !bg-transparent !opacity-0"
                position={data.isLeft ? Position.Right : Position.Left}
                type="target"
            />
            {data.isRead ? (
                <GlyphMark icon={CheckCircleIcon} tone="success" />
            ) : null}
            <span className="line-clamp-2 leading-snug">{data.label}</span>
        </button>
    )
}

/** Folder-matching handle for the module-slot node — an alias of {@link CourseModuleSlotNode}. */
export const ModuleSlotNode = CourseModuleSlotNode

"use client"

import React, { useCallback, useEffect, useRef, useState } from "react"
import {
    Button,
    cn,
} from "@heroui/react"
import { SparkleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useSmViewpoint } from "@/hooks/reuseables/useSmViewpoint"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { useContentAiChatOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useContentAiChatModeStore } from "@/hooks/zustand/contentAiChatMode/store"
import { FloatingActionButton } from "@/components/blocks/buttons/FloatingActionButton"

/** localStorage key for the FAB's persisted vertical position (px from viewport bottom). */
const STORAGE_KEY = "contentAiFabBottom"
/** Default distance from the viewport bottom (px). */
const DEFAULT_BOTTOM = 96
/** Lowest the FAB may sit (px from bottom) — keeps it clear of the very edge. */
const MIN_BOTTOM = 16
/** Pixels the pointer must travel before a press counts as a drag (not a click). */
const DRAG_THRESHOLD = 6
/** Headroom kept below the top edge so the FAB never drags off-screen (px). */
const TOP_GUARD = 80

/** Props for {@link ContentAiFab}. */
export type ContentAiFabProps = WithClassNames<undefined>

/**
 * Floating "ask StarCi AI" button — the TRIGGER for the app-wide chat, mounted
 * ONCE by `InnerLayout` so it is reachable from EVERY route, not just a course's
 * learn surface: with a lesson open it grounds on that lesson, with a course but
 * no lesson it grounds on the course, and with no course at all (e.g. the
 * dashboard) it opens a `global`, anchorless conversation — see the scope ladder
 * in {@link import("@/components/blocks/learn/ContentAiChat").ContentAiChat}.
 * The panel is presented per the learner's persisted choice
 * ({@link useContentAiChatModeStore}), switchable in the panel header:
 * - **rail** — a resizable right-edge side panel that reflows the app column
 *   (see `InnerLayout`'s split); the FAB here is only the draggable toggle,
 *   hidden while the rail is open (the rail carries its close).
 * - **drawer** — the slide-in {@link import("@/components/overlays/drawers/ContentAiChatDrawer").ContentAiChatDrawer}
 *   (rendered globally); the FAB is its trigger.
 *
 * MOBILE always uses the drawer regardless of the preference. Open-state lives in
 * the shared overlay store (`contentAiChat` key).
 *
 * @param props - {@link ContentAiFabProps}
 */
export const ContentAiFab = ({ className }: ContentAiFabProps) => {
    const t = useTranslations()
    const { isOpen, setOpen, open } = useContentAiChatOverlayState()
    const { mode } = useContentAiChatModeStore()
    const { isMobile } = useSmViewpoint()
    // a phone is always the drawer — a side rail is too cramped there.
    const effectiveMode = isMobile ? "drawer" : mode

    // vertical position of the FAB (px from viewport bottom); restored from localStorage on mount
    const [bottom, setBottom] = useState<number>(DEFAULT_BOTTOM)
    useEffect(() => {
        // localStorage is client-only; read once after mount to seed the persisted position
        const saved = window.localStorage.getItem(STORAGE_KEY)
        if (saved !== null && !Number.isNaN(Number(saved))) {
            setBottom(Number(saved))
        }
    }, [])

    // drag bookkeeping: a press opens the panel ONLY when it did not become a drag
    const draggingRef = useRef(false)
    const startRef = useRef<{ pointerY: number; bottom: number } | null>(null)

    // remember where the drag began so we can offset from it
    const onPointerDown = useCallback(
        (event: React.PointerEvent) => {
            startRef.current = { pointerY: event.clientY, bottom }
            draggingRef.current = false
            event.currentTarget.setPointerCapture?.(event.pointerId)
        },
        [bottom],
    )

    // move the FAB up/down with the pointer, clamped to the viewport; mark it a drag past the threshold
    const onPointerMove = useCallback((event: React.PointerEvent) => {
        const start = startRef.current
        if (!start) {
            return
        }
        // dragging UP (smaller clientY) should RAISE the bubble → larger `bottom`
        const delta = start.pointerY - event.clientY
        if (Math.abs(delta) > DRAG_THRESHOLD) {
            draggingRef.current = true
        }
        const maxBottom = window.innerHeight - TOP_GUARD
        setBottom(Math.min(Math.max(start.bottom + delta, MIN_BOTTOM), maxBottom))
    }, [])

    // end the gesture; persist the new position only if it was actually a drag
    const onPointerUp = useCallback(
        (event: React.PointerEvent) => {
            if (startRef.current && draggingRef.current) {
                window.localStorage.setItem(STORAGE_KEY, String(bottom))
            }
            startRef.current = null
            event.currentTarget.releasePointerCapture?.(event.pointerId)
        },
        [bottom],
    )

    // a real press (not a drag) opens the panel; swallow the click that fires at the
    // end of a drag-release.
    const onOpen = useCallback(() => {
        if (draggingRef.current) {
            draggingRef.current = false
            return
        }
        setOpen(true)
    }, [setOpen])

    // No course-required gate any more: with no course at all (dashboard,
    // profile, …) the chat just opens `global`-scoped instead of hiding itself —
    // see the scope ladder in `ContentAiChat`.

    // DRAWER — the panel is the global ContentAiChatDrawer; here just the FAB trigger.
    if (effectiveMode === "drawer") {
        return (
            <FloatingActionButton
                onPress={open}
                ariaLabel={t("contentAi.ask")}
                className={className}
            >
                {/* sparkle = AI intent; the wrapped isIconOnly button sizes the svg */}
                <SparkleIcon />
            </FloatingActionButton>
        )
    }

    // RAIL — the resizable rail is rendered by the learn shell (rightRail) when open.
    // The FAB is the draggable toggle, hidden while the rail is open (the rail closes itself).
    if (isOpen) {
        return null
    }

    return (
        <Button
            isIconOnly
            variant="primary"
            aria-label={t("contentAi.ask")}
            aria-expanded={isOpen}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={onPointerUp}
            onPress={onOpen}
            style={{ bottom }}
            className={cn(
                "fixed right-[calc(var(--app-rail-w,0px)+1rem)] z-40 mb-[env(safe-area-inset-bottom)] touch-none rounded-full shadow-lg",
                className,
            )}
        >
            {/* sparkle = AI intent; the isIconOnly button sizes the svg itself */}
            <SparkleIcon />
        </Button>
    )
}

import React, { useState } from "react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { ThreadConnector } from "@/components/atoms/display/ThreadConnector"
import { Typography } from "@/components/atoms/text/Typography"
import { IdentityContentRow } from "@/components/composites/lists/IdentityContentRow"
import { StackH, StackV } from "@/components/frames/Stack"
import { ContentCommentComposer, type ContentCommentComposerViewer } from "@/components/blocks/learn/ContentCommentComposer"
import { ReactionButton, type ReactionType, type ReactionCount } from "@/components/blocks/learn/ReactionButton"

/**
 * BLOCK — `ContentCommentThread`: one threaded comment — author, reaction,
 * reply/edit/delete actions, and its recursively-rendered replies. Ported
 * verbatim from real `src`'s `CommentItem`. See the component's own file
 * header for the massive gap this fills against the earlier flat-list cut.
 *
 * 📐 LEAVES by STRUCTURE (§14d.2). Owner-only actions appearing, the body
 * swapping for an edit composer or a deleted placeholder, and the reply
 * subtree expanding each add/remove real nodes ⇒ separate leaves.
 */

/** Minimal identity for a comment's author. */
export interface ContentCommentAuthor {
    id: string
    username: string
    avatarUrl?: string
}

/** One comment (or, at `depth > 0`, one reply). */
export interface ContentCommentNode {
    /** Stable id — also what reply/edit/delete/react target. */
    id: string
    author: ContentCommentAuthor
    /** Already-formatted relative time, e.g. "2 hours ago". */
    createdTimeAgo: string
    /** `true` → a founder badge rides beside the author name. */
    isFounderAuthor?: boolean
    /** `true` → the body was edited after posting; shows a quiet "(edited)" marker. */
    isEdited?: boolean
    /** `true` → the body is replaced with a "removed" placeholder; no actions render. */
    isDeleted?: boolean
    /** The comment text (ignored when `isDeleted`). */
    body: string
    /** Total replies under this comment (drives the "view replies" toggle). */
    replyCount: number
    /** The viewer's own reaction on this comment, or `null`. */
    myReaction: ReactionType | null
    /** Per-emotion reaction counts on this comment. */
    reactionCounts?: ReadonlyArray<ReactionCount>
}

/** Callbacks shared down the comment tree — same shape at every depth. */
export interface ContentCommentThreadCallbacks {
    onReply: (parentId: string, body: string) => void
    onEdit: (commentId: string, body: string) => void
    onDelete: (commentId: string) => void
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load a parent's replies — fired the first time its subtree expands. */
    onLoadReplies: (parentId: string) => void
}

/** Props for the module-scope {@link CommentByline} helper. */
interface CommentBylineProps {
    username: string
    isFounderAuthor?: boolean
    createdTimeAgo: string
    isEdited?: boolean
}

/**
 * `IdentityContentRow.byline` — a component reference (COMPOSITE-8), not a
 * built element. Kept at MODULE scope (not defined inline inside
 * `ContentCommentThread`'s body) and fed only read-only per-comment fields as
 * props, so passing a fresh wrapping arrow each render never risks remounting
 * anything stateful — there is no state in this leaf to lose.
 */
const CommentByline = ({ username, isFounderAuthor, createdTimeAgo, isEdited }: CommentBylineProps) => (
    <StackH
        gap={2}
        principle="separator-dot"
        explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
        align="center"
        items={[
            () => (
                <StackH
                    gap={2}
                    principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="center"
                    items={[
                        () => <Typography size="sm" weight="medium" text={username} />,
                        ...(isFounderAuthor ? [() => (
                            <SealCheckIcon weight="fill" aria-label="Founder" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                        )] : []),
                    ]}
                />
            ),
            () => <Typography size="xs" color="muted" text={createdTimeAgo} />,
            ...(isEdited ? [() => (
                <Typography size="xs" color="muted" text="(edited)" />
            )] : []),
        ]}
    />
)

/** Props for {@link ContentCommentThread}. */
export interface ContentCommentThreadProps extends ContentCommentThreadCallbacks {
    /** The comment to render. */
    comment: ContentCommentNode
    /** Current viewer id — drives owner-only edit/delete; null when signed out. */
    currentUserId: string | null
    /**
     * Current viewer identity for the reply composer's own avatar (Facebook-style
     * nested reply) — `null`/omitted → reply composer renders with no avatar. Real
     * `CommentComposer` never shows one at all; this is a deliberate divergence, not
     * a `src` port.
     */
    currentUser?: ContentCommentComposerViewer | null
    /** Nesting depth — 0 for a top-level comment, `depth + 1` for each reply. */
    depth: number
    /** Already-loaded replies, keyed by parent id (empty until `onLoadReplies` resolves). */
    repliesByParent: Record<string, ReadonlyArray<ContentCommentNode>>
}

/**
 * One threaded comment. See the file header for the full contract.
 *
 * @param props - {@link ContentCommentThreadProps}
 */
const ContentCommentThread = ({
    comment,
    currentUserId,
    currentUser,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies,
}: ContentCommentThreadProps) => {
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    // action row: reaction + reply + owner edit/delete. `isButton`, NOT `isLink` — real
    // src's own action links carry no underline at all, only a resting→hover COLOR
    // shift, which isLink's underline treatment would misrepresent.
    const actionRow = (
        <>
            <ReactionButton
                myReaction={comment.myReaction}
                counts={comment.reactionCounts}
                onReact={(type) => onReactComment(comment.id, type)}


            />
            <Typography
                size="xs"
                weight="medium"
                color="muted"
                isButton
                hoverColor="default"
                text="Reply"
                onPress={() => setReplying((prev) => !prev)}

            />
            {isOwner ? (
                <>
                    <Typography
                        size="xs"
                        weight="medium"
                        color="muted"
                        isButton
                        hoverColor="default"
                        text="Edit"
                        onPress={() => setEditing(true)}

                    />
                    <Typography
                        size="xs"
                        weight="medium"
                        color="muted"
                        isButton
                        hoverColor="danger"
                        text="Delete"
                        onPress={() => onDelete(comment.id)}

                    />
                </>
            ) : null}
        </>
    )

    const bodyAndActions = (
        <>
            {/* body, edit form, or deleted placeholder */}
            {comment.isDeleted ? (
                <Typography size="sm" color="muted" isItalic text="[Comment removed]" />
            ) : editing ? (
                <ContentCommentComposer
                    initialValue={comment.body}
                    submitLabel="Save"
                    ariaLabel="Edit comment"
                    onCancel={() => setEditing(false)}
                    onSubmit={(body) => {
                        onEdit(comment.id, body)
                        setEditing(false)
                    }}

                />
            ) : (
                <Typography size="sm" preserveWhitespace text={comment.body} />
            )}

            {!comment.isDeleted && !editing ? (
                <StackH gap={4} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    at="sm" align="center" items={[() => actionRow]}  />
            ) : null}
        </>
    )

    const threadBody = (
        <>
            <StackV gap={2} items={[() => bodyAndActions]} />

            {/* reply composer — `ThreadConnector` draws the Facebook-style curved
                guide from this comment down into the reply's own avatar;
                `currentUser` is what gives the composer an avatar to connect TO
                in the first place (see its own file header). */}
            {replying ? (
                <StackH
                    gap={2}
                    principle="icon-text"
                    explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                    align="start"

                    items={[
                        () => <ThreadConnector />,
                        () => (
                            <ContentCommentComposer
                                placeholder="Write a reply..."
                                submitLabel="Reply"
                                ariaLabel="Write a reply"
                                currentUser={currentUser}
                                classNames={["min-w-0", "flex-1"]}
                                onCancel={() => setReplying(false)}
                                onSubmit={(body) => {
                                    onReply(comment.id, body)
                                    setReplying(false)
                                    setExpanded(true)
                                    onLoadReplies(comment.id)
                                }}

                            />
                        ),
                    ]}
                />
            ) : null}

            {/* replies toggle + recursive subtree */}
            {comment.replyCount > 0 ? (
                <Typography
                    size="xs"
                    weight="medium"
                    color="accent"
                    isLink
                    underlineOnHover
                    text={expanded ? "Hide replies" : `View ${comment.replyCount} replies`}
                    onPress={toggleReplies}

                />
            ) : null}

            {expanded && replies.length > 0 ? (
                <StackV
                    gap={4}

                    items={replies.map((reply) => () => (
                        <ContentCommentThread
                            comment={reply}
                            currentUserId={currentUserId}
                            currentUser={currentUser}
                            depth={depth + 1}
                            repliesByParent={repliesByParent}
                            onReply={onReply}
                            onEdit={onEdit}
                            onDelete={onDelete}
                            onReactComment={onReactComment}
                            onLoadReplies={onLoadReplies}

                        />
                    ))}
                />
            ) : null}
        </>
    )

    return (
        // `IdentityContentRow` (composite) owns the avatar+byline+column shape — both
        // its seams are `tight` ON PURPOSE, a denser standalone treatment, NOT a
        // `src`-fidelity port (see the composite's own file header). `nested` draws the
        // reply indent guide via the `Stack` frame prop.
        <IdentityContentRow
            avatarSrc={comment.author.avatarUrl}
            avatarName={comment.author.username}
            avatarSeed={comment.author.id}
            avatarSize="sm"
            nested={depth > 0}


            byline={() => (
                <CommentByline
                    username={comment.author.username}
                    isFounderAuthor={comment.isFounderAuthor}
                    createdTimeAgo={comment.createdTimeAgo}
                    isEdited={comment.isEdited}
                />
            )}
            // `body` is the former `children` slot (COMPOSITE-8) — a component
            // reference, not a built node. `threadBody` (StackV wrapping
            // bodyAndActions + reply composer + replies subtree) is already
            // computed above per the current render's state, so the wrapper here
            // only needs to hand it back.
            body={() => (
                /* `grouped` — separates [body+actions, tight together] from whatever
                    comes after a reply composer/toggle/subtree: the seam right before
                    a reply composer appears needs more
                    room than the tight identity block above it (also where the
                    Facebook-style connector line will run). */
                <StackV gap={4} items={[() => threadBody]} />
            )}
        />
    )
}

export { ContentCommentThread }

"use client"

import React, {
    useCallback,
    useEffect,
    useMemo,
    useState,
} from "react"
import {
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { OutlineRail } from "@/components/blocks/navigation/OutlineRail"
import type { OutlineRailGroup } from "@/components/blocks/navigation/OutlineRail"
import type { MyCourseOutlineModule } from "@/modules/api/graphql/queries/types/my-course-outline"

/**
 * Filter modules + their lessons by a lower-cased query (module title match keeps
 * all its lessons; otherwise only matching lessons survive). Empty query → unchanged.
 *
 * @param modules - The course's modules.
 * @param query - Lower-cased trimmed search query.
 * @returns The filtered modules.
 */
const filterModules = (
    modules: Array<MyCourseOutlineModule>,
    query: string,
): Array<MyCourseOutlineModule> => {
    if (!query) {
        return modules
    }
    const result: Array<MyCourseOutlineModule> = []
    for (const module of modules) {
        const moduleMatches = module.title.toLowerCase().includes(query)
        const lessons = moduleMatches
            ? module.lessons
            : module.lessons.filter((lesson) => lesson.title.toLowerCase().includes(query))
        if (moduleMatches || lessons.length > 0) {
            result.push({ ...module, lessons })
        }
    }
    return result
}

/**
 * Content-map rail — the lean docs-style course navigation tree shown to the left
 * while reading (module → lesson, read/premium markers, a progress header with a
 * "continue" action). A thin data wrapper: owns the `myCourseOutline` SWR + Redux
 * selection + routing + the controlled search/expand state, and renders the shared
 * {@link OutlineRail} block (which owns the look it shares with the personal-project
 * milestone rail).
 *
 * Positioning (sticky / width / scroll) is owned by the learn shell's
 * {@link FillAvailable} wrapper on desktop and the mobile drawer on small screens.
 */
export const ContentMap = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    const activeContentId = useAppSelector((state) => state.content.id)

    const outlineSwr = useQueryMyCourseOutlineSwr(courseId ?? null)
    const outline = outlineSwr.data

    const [search, setSearch] = useState("")
    const query = search.trim().toLowerCase()
    const modules = useMemo(
        () => (outline ? filterModules(outline.modules, query) : []),
        [outline, query],
    )

    /** Module owning the active lesson — expanded on first paint. */
    const activeModuleId = useMemo(() => {
        if (!outline || !activeContentId) {
            return undefined
        }
        return outline.modules.find((module) =>
            module.lessons.some((lesson) => lesson.id === activeContentId))?.id
    }, [outline, activeContentId])

    /**
     * Expanded modules (controlled) — only the open module shows its read-progress
     * bar; collapsed ones show a compact "n/m" count instead. The active lesson's
     * module auto-opens; a search opens every matching module so hits are visible.
     */
    const [expandedKeys, setExpandedKeys] = useState<Set<string>>(new Set())
    useEffect(() => {
        if (!activeModuleId) {
            return
        }
        setExpandedKeys((prev) => prev.has(activeModuleId) ? prev : new Set(prev).add(activeModuleId))
    }, [activeModuleId])
    useEffect(() => {
        if (query) {
            setExpandedKeys(new Set(modules.map((module) => module.id)))
        }
    }, [query, modules])

    const progress = outline?.progress
    const currentTask = outline?.currentTask

    /**
     * Route for the "continue" button from `currentTask`. Lessons route straight to
     * their content; challenges route to the owning lesson's challenges tab. Milestone
     * tasks have no rail route yet → null (button hidden).
     */
    const continueHref = useMemo(() => {
        if (!outline || !currentTask || !displayId) {
            return null
        }
        const base = (moduleId: string, contentId: string) =>
            pathConfig().locale(locale).course(displayId).learn().module(moduleId).content(contentId).build()
        if (currentTask.kind === "lesson") {
            const owner = outline.modules.find((module) =>
                module.lessons.some((lesson) => lesson.id === currentTask.id))
            return owner ? base(owner.id, currentTask.id) : null
        }
        if (currentTask.kind === "challenge") {
            for (const module of outline.modules) {
                const lesson = module.lessons.find((item) =>
                    item.challenges.some((challenge) => challenge.id === currentTask.id))
                if (lesson) {
                    return `${base(module.id, lesson.id)}?tab=challenges`
                }
            }
        }
        return null
    }, [outline, currentTask, displayId, locale])

    /** Jump to the viewer's current task. */
    const onContinue = useCallback(() => {
        if (continueHref) {
            router.push(continueHref)
        }
    }, [continueHref, router])

    /** Navigate to the chosen lesson within its module. */
    const onSelectLesson = useCallback(
        (lessonId: string, moduleId: string) => {
            if (!displayId) {
                return
            }
            router.push(
                pathConfig().locale(locale).course(displayId).learn().module(moduleId).content(lessonId).build(),
            )
        },
        [router, locale, displayId],
    )

    /** Navigate to the dedicated module page (title press — caret still toggles). */
    const onOpenModule = useCallback(
        (moduleId: string) => {
            if (!displayId) {
                return
            }
            router.push(
                pathConfig().locale(locale).course(displayId).learn().module(moduleId).build(),
            )
        },
        [router, locale, displayId],
    )

    /** modules → milestone-agnostic rail groups (read markers, minutes meta). */
    const groups = useMemo<Array<OutlineRailGroup>>(
        () => modules.map((module) => {
            const readCount = module.lessons.filter((lesson) => lesson.isRead).length
            return {
                id: module.id,
                title: module.title,
                progress: { done: readCount, total: module.lessons.length },
                collapsedCountLabel: t("courseContents.moduleLessons", {
                    read: readCount,
                    total: module.lessons.length,
                }),
                onTitlePress: () => onOpenModule(module.id),
                items: module.lessons.map((lesson) => ({
                    id: lesson.id,
                    title: lesson.title,
                    isActive: lesson.id === activeContentId,
                    isRead: lesson.isRead,
                    isPremium: lesson.isPremium,
                    meta: (
                        <Typography type="body-xs" color="muted">
                            {t("content.minutesShort", { minutes: lesson.minutesRead })}
                        </Typography>
                    ),
                    onPress: () => onSelectLesson(lesson.id, module.id),
                })),
            }
        }),
        [modules, activeContentId, onSelectLesson, onOpenModule, t],
    )

    return (
        <OutlineRail
            header={progress ? {
                label: t("courseContents.progress"),
                progress: { done: progress.lessonsRead, total: progress.lessonsTotal },
                countLabel: t("courseContents.contentCount", {
                    read: progress.lessonsRead,
                    total: progress.lessonsTotal,
                }),
                // only when you've navigated AWAY from your current task — hide it while
                // you're already reading that task (the button would just point at this page).
                continue: continueHref && currentTask?.id !== activeContentId ? {
                    label: t("courseContents.resume"),
                    onPress: onContinue,
                } : undefined,
            } : undefined}
            search={{
                value: search,
                onChange: setSearch,
                placeholder: t("courseContents.searchPlaceholder"),
                ariaLabel: t("courseContents.searchAria"),
            }}
            groups={groups}
            expandedKeys={expandedKeys}
            onExpandedChange={setExpandedKeys}
            isSkeleton={!outlineSwr.data && !outlineSwr.error}
            async={{
                isEmpty: !outline,
                emptyTitle: t("courseContents.empty"),
                errorTitle: t("courseContents.error"),
                error: !outlineSwr.data ? outlineSwr.error : undefined,
                onRetry: () => { void outlineSwr.mutate() },
                retryLabel: t("courseContents.retry"),
                noMatchLabel: t("courseContents.noMatch"),
            }}
        />
    )
}

export default ContentMap

import React from "react"
import { PageHeader } from "@/components/composites/layout/Page"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * `CourseBrief` — the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `·`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     * ⛔ NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules · ~14h · 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator —
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `·`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) — the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners — the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` → the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data — the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (§12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS — units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (§14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={
                breadcrumbItems?.length
                    ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                        // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                        <div className="w-fit">
                            {/* collapse: below @app-sm or trail ≥ 4 crumbs → back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={skeleton}
                            />
                        </div>
                    )
                    : undefined
            }
            title={title}
            description={description}
            meta={
                metaParts.length > 0
                    ? () => (
                        <Typography size="xs" color="muted" text={metaParts.join(" · ")} />
                    )
                    : undefined
            }
        />
    )
}

/** `CourseBrief.*` — single-component namespace ⇒ only `.Base`. */
export { CourseBriefBase as CourseBrief }

"use client"

import React, { useCallback } from "react"
import { ArrowRightIcon, LockIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"
import { useAppSelector } from "@/redux/hooks"
import { useQueryCoursePricePreviewSwr } from "@/hooks/swr/api/graphql/queries/useQueryCoursePricePreviewSwr"
import { AsyncContentError } from "@/components/composites/async/AsyncContent"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { PhaseScarcityNote } from "@/components/blocks/commerce/PhaseScarcityNote"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** The conversion card's own surface: a bounded, floating sheet no frame names. */
const CARD_SURFACE = "flex w-full max-w-[480px] flex-col items-center gap-3 rounded-3xl bg-surface px-7 py-8 text-center shadow-surface"

/**
 * Fade band over the teaser's tail. It fades into the preview's OWN card token
 * (`bg-surface`), not the page canvas — the teaser content is bg-surface cards, so
 * fading to `background` cut them off mid-card. Same band height as LessonReader's
 * locked-body fade — canonical value, not re-tuned here.
 */
const TEASER_FADE = "absolute inset-x-0 bottom-0 h-72 bg-gradient-to-b from-transparent via-surface/70 to-surface"

interface EnrollCardProps {
    title: string
    description: string
    priceRegion: () => React.ReactNode
    scarcity?: () => React.ReactNode
    ctaLabel: string
    onEnroll: () => void
}

const EnrollCard = ({ title, description, priceRegion, scarcity, ctaLabel, onEnroll }: EnrollCardProps) => (
    <Box className={CARD_SURFACE}>
        <StackV
            gap={4}
            principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            align="center"
            items={[
                () => <IconTile icon={<LockIcon aria-hidden focusable="false" />} tone="accent" size="sm" />,
                () => <Typography size="h4" weight="bold" text={title} />,
                () => (
                    <Box className="max-w-[400px]">
                        <Typography size="sm" color="muted" text={description} />
                    </Box>
                ),
                priceRegion,
                ...(scarcity ? [scarcity] : []),
                () => (
                    <Box className="w-full max-w-[300px]">
                        <Button
                            label={ctaLabel}
                            variant="primary"
                            size="lg"
                            suffixIcon={ArrowRightIcon}
                            onPress={onEnroll}
                            classNames={["w-full"]}
                        />
                    </Box>
                ),
            ]}
        />
    </Box>
)

/** Props for {@link EnrollGate}. */
export interface EnrollGateProps {
    /** Title — e.g. "Unlock Personal project" (the surface name folded in by the caller). */
    title: string
    /** One-line reason the surface needs enrollment. */
    description: string
    /**
     * Optional MOCK teaser of the gated surface (representative, non-interactive
     * content — NOT real gated data). When provided, the gate reads Medium-style:
     * the preview is rendered `aria-hidden` behind a bottom fade, with the enroll
     * card floating over the faded tail — so the learner SEES what's inside before
     * the CTA. Omit → just the centred enroll card (no teaser).
     */
    preview?: React.ReactNode
}

/**
 * Course-surface enroll gate: shown in place of an enrollment-required learn surface
 * (personal-project, mock-interview, flashcards, module) when the viewer is in trial
 * mode (not enrolled). Instead of a dead grey card, it renders a conversion CARD —
 * lock identity + outcome copy + the loyalty-aware {@link PriceTag} + scarcity + a
 * single enroll CTA (mirrors {@link import("../../LessonReader/PremiumPaywall").PremiumPaywall},
 * SAME price source/render as the payment modal). With a {@link EnrollGateProps.preview}
 * it upgrades to a Medium-style teaser: a faded mock of the surface behind the card.
 * The single action enrolls via the shared {@link PaymentFlow.CourseEnroll} modal.
 *
 * Only the PRICE waits on a fetch — the lock, copy and CTA render straight away.
 *
 * @param props - {@link EnrollGateProps}
 */
export const EnrollGate = ({ title, description, preview }: EnrollGateProps) => {
    const t = useTranslations()
    const { open } = usePaymentOverlayState()
    const courseId = useAppSelector((state) => state.course.entity?.id)

    // loyalty-aware price preview — SAME query/render as PaymentModal + PremiumPaywall
    const priceSwr = useQueryCoursePricePreviewSwr(courseId ?? null)
    const price = priceSwr.data
    const isPriceSkeleton = Boolean(courseId) && !priceSwr.data && !priceSwr.error

    /** Open the shared payment modal in the course-enroll flow. */
    const onEnroll = useCallback(
        () => open({ flow: PaymentFlow.CourseEnroll }),
        [open],
    )

    // error beats a stale loading flag (BLOCK-8 order)
    const priceRegion = () => {
        if (priceSwr.error) {
            return <AsyncContentError title={t("payment.priceError")} />
        }
        if (isPriceSkeleton) {
            return <Skeleton className="h-7 w-32 rounded-xl" />
        }
        return price?.discountedPriceVnd != null ? (
            <PriceTagInline
                discounted={price.discountedPriceVnd}
                original={price.originalPriceVnd}
               
                breakdown={{
                    phase: price.phasePriceVnd,
                    loyaltyPercent: price.discountPercent,
                }}
            />
        ) : null
    }

    const scarcity = price
        ? () => (
            <PhaseScarcityNote
                currentPhase={price.currentPhase}
                seatsRemaining={price.seatsRemainingInCurrentPhase}
                nextPhasePriceVnd={price.nextPhasePriceVnd}
            />
        )
        : undefined

    // no teaser → just the centred enroll card.
    // Asymmetric page inset {x:5,y:6} has no padding principle token; a StackV
    // that also carried gap={1} was padding-plus-gap with no honest owner — Box
    // keeps the same inset without a false seam token.
    if (!preview) {
        return (
            <Box
                identity={{ tier: "block", component: "EnrollGate" }}
                className="flex justify-center px-5 py-6"
            >
                <EnrollCard
                    title={title}
                    description={description}
                    priceRegion={priceRegion}
                    scarcity={scarcity}
                    ctaLabel={t("enrollGate.cta")}
                    onEnroll={onEnroll}
                />
            </Box>
        )
    }

    // teaser → the FULL real preview (no height cap — mirrors LessonReader, which renders
    // the whole real body and only fades its tail, never truncates early), with the enroll
    // card floating over the faded tail. The stack, the fade and the overlap are positional
    // values no frame names, so they stay literals on Box.
    return (
        <Box identity={{ tier: "block", component: "EnrollGate" }} className="relative">
            <Box className="pointer-events-none relative" aria-hidden>
                {preview}
                <Box className={TEASER_FADE} />
            </Box>
            <Box className="relative z-10 -mt-32 flex justify-center px-4 pb-6">
                <EnrollCard
                    title={title}
                    description={description}
                    priceRegion={priceRegion}
                    scarcity={scarcity}
                    ctaLabel={t("enrollGate.cta")}
                    onEnroll={onEnroll}
                />
            </Box>
        </Box>
    )
}

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `FoundationCategoryHeader` — the Foundations-hub identity cluster: a breadcrumb
 * trail above a title and description, nothing more. Sibling of `ContentHeader`
 * but thinner — a Foundations category carries no read state, reading time, or
 * outcomes, so it stops at the description. The breadcrumb slot is optional and
 * simply drops out when absent.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface FoundationCategoryHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link FoundationCategoryHeader}. */
export interface FoundationCategoryHeaderProps {
    /**
     * Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. Empty
     * or omitted (and not loading) → the whole breadcrumb slot is left out: a
     * root category reached directly has nothing above it to trail through.
     */
    breadcrumbItems?: Array<FoundationCategoryHeaderCrumb>
    /** Category title. */
    title: string
    /** One-sentence summary of the category. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Foundations-hub identity cluster: trail, title, description. See the file
 * header for why this stops short of `ContentHeader`'s meta row and outcomes
 * card, and why it still earns its own layer above `PageHeader`.
 *
 * @param props - {@link FoundationCategoryHeaderProps}
 */
const FoundationCategoryHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: FoundationCategoryHeaderProps) => {
    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || breadcrumbItems?.length ? (
                    // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems ?? []}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
        />
    )
}

export { FoundationCategoryHeader }

import React from "react"
import { CaretRightIcon, MagnifyingGlassIcon, StackIcon } from "@phosphor-icons/react"
import { IconTile } from "@/components/atoms/display/IconTile"
import { Chip } from "@/components/atoms/chips/Chip"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Pagination } from "@/components/atoms/navigation/Pagination"
import { Cluster } from "@/components/frames/Cluster"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { StackV } from "@/components/frames/Stack"

/**
 * `FoundationResourceList` — the resource browse list: numbered rows of
 * supplementary material the learner can search and page through. Composes
 * `AsyncContent` (error/loading/empty/content switch), `SurfaceCardList` (bounded
 * rows + loading mirror), `IconTile` (cover image falling back to a glyph),
 * `EnumChip`/`Chip`, and `Pagination`; the block owns the numbering, kind labels,
 * recommended text, and the "no resources yet" vs `no matches for "X"` wording.
 */

/** The kind of resource a row points at — drives the kind chip's label/color. */
export type FoundationKindEnum = "article" | "video" | "exercise" | "reference"

/** One resource row — plain DATA; the block builds the numbering, chips and caret. */
export interface FoundationResourceItem {
    /** Stable id — the React key. */
    id: string
    /** Resource title — the block prefixes it with its position ("1. …"). */
    title: string
    /** One-line blurb under the title. */
    description?: string
    /** Cover thumbnail. Falls back to a `StackIcon` glyph — see file header. */
    thumbnailUrl?: string
    /** Drives the kind chip via {@link KIND_CHIP_MAP}. */
    kind: FoundationKindEnum
    /** `true` → an extra "Recommended" chip rides beside the kind chip. */
    isRecommended?: boolean
    /** Fired when the row is pressed. */
    onPress: () => void
}

/** Props for {@link FoundationResourceList}. */
export interface FoundationResourceListProps {
    /** The current page's resources, in display order. REQUIRED — see file header §R0. */
    resources: Array<FoundationResourceItem>
    /** `true` → the list's own fetch is in flight; own LEAF (see file header). */
    isLoading: boolean
    /** Truthy → the list falls to its error message; own LEAF (beats loading/empty). */
    error?: unknown
    /** Current search text, if the list is filtered. Decides which empty message shows. */
    searchQuery?: string
    /** 1-based current page. */
    currentPage: number
    /** Total page count. */
    totalPages: number
    /** Fired with the 1-based page the viewer picked. */
    onPageChange: (pageNumber: number) => void
    /** Accessible name for the list region — the block has no visible heading of its own. */
    ariaLabel?: string
}

/** kind → chip label/color — the block's own vocabulary (§14d.1), never handed in by a caller. */
const KIND_CHIP_MAP: Record<FoundationKindEnum, EnumChipEntry> = {
    article: { label: "Article" },
    video: { label: "Video", color: "accent" },
    exercise: { label: "Exercise", color: "warning" },
    reference: { label: "Reference", color: "success" },
}

/** The block's own wording for the recommended chip. */
const RECOMMENDED_LABEL = "Recommended"

const ERROR_TITLE = "Could not load the resource list"
const EMPTY_TITLE_NO_QUERY = "No resources here yet"
const EMPTY_DESCRIPTION_WITH_QUERY = "Try a different keyword."

/** How many placeholder rows mirror the list while `resources` hasn't landed yet. */
const SKELETON_ROW_COUNT = 4

/** One row's kind chip + optional recommended chip, in that order. */
const resourceMeta = (resource: FoundationResourceItem) => {
    const chips: Array<ComponentTypeWithSkeleton> = [
        () => <EnumChip value={resource.kind} map={KIND_CHIP_MAP} />,
        ...(resource.isRecommended ? [() => <Chip tone="accent" text={RECOMMENDED_LABEL} />] : []),
    ]
    return <Cluster gap={3} items={chips} />
}

/** Placeholder rows for the loading mirror — no data, no press handler (§12c). */
const skeletonRows = (): Array<SurfaceCardListItem> =>
    Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        leading: () => <IconTile isSkeleton size="sm" />,
        title: "",
        subtitle: "",
    }))

/** One real row: numbered title, blurb, thumbnail-or-glyph, kind+recommended chips, caret. */
const resourceRow = (resource: FoundationResourceItem, position: number): SurfaceCardListItem => ({
    key: resource.id,
    leading: () => (
        <IconTile
            src={resource.thumbnailUrl}
            icon={StackIcon}
            size="sm"

        />
    ),
    // The block owns the numbering (§14d.1) — see file header for why it is
    // LOCAL to the current page rather than a running count across pages.
    title: `${position}. ${resource.title}`,
    subtitle: resource.description,
    meta: () => resourceMeta(resource),
    trailingIcon: CaretRightIcon,
    onPress: resource.onPress,
})

/**
 * The resource browse list. See the file header for the full contract, the
 * leaf boundary reasoning, and the judgement calls (local numbering, pager
 * placement, no retry action, `ariaLabel` as the region's only name).
 *
 * @param props - {@link FoundationResourceListProps}
 */
const FoundationResourceList = ({
    resources,
    isLoading,
    error,
    searchQuery,
    currentPage,
    totalPages,
    onPageChange,
    ariaLabel,
}: FoundationResourceListProps) => {
    const hasQuery = Boolean(searchQuery && searchQuery.trim().length > 0)

    const emptyContent: AsyncContentEmptyProps = hasQuery
        ? {
            icon: MagnifyingGlassIcon,
            title: `No resources found matching "${searchQuery}"`,
            description: EMPTY_DESCRIPTION_WITH_QUERY,

        }
        : {
            title: EMPTY_TITLE_NO_QUERY,

        }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,

    }

    const rows: Array<SurfaceCardListItem> = resources.map((resource, index) => resourceRow(resource, index + 1))

    return (
        <div aria-label={ariaLabel} role={ariaLabel ? "region" : undefined}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <SurfaceCardList
                        items={skeletonRows()}
                        isSkeleton

                    />
                )}
                isEmpty={resources.length === 0}
                emptyContent={emptyContent}
                error={error}
                errorContent={errorContent}

                content={() => (
                    <StackV
                        gap={3}

                        items={[
                            () => <SurfaceCardList items={rows} />,
                            () => (
                                <div>
                                    <Pagination
                                        currentPage={currentPage}
                                        totalPages={totalPages}
                                        onPageChange={onPageChange}

                                    />
                                </div>
                            ),
                        ]}
                    />
                )}
            />
        </div>
    )
}

export { FoundationResourceList }

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { TrophyIcon } from "@phosphor-icons/react"
import { SurfaceCard, SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { UserCell } from "@/components/composites/lists/UserCell"
import { IconTile } from "@/components/atoms/display/IconTile"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { FillAvailable } from "@/components/frames/FillAvailable"
import { Podium } from "../Podium"
import { type BoardProps, type LeaderboardRow } from "../types"

/** Builds one row's free-form `SurfaceCard.List` content: rank number + the unchanged `UserCell`. */
const rowItem = (row: LeaderboardRow, meLabel: string, isSkeleton: boolean): SurfaceCardListItem => ({
    key: row.key,
    href: row.profileHref,
    content: () => (
        <StackH
            gap={3}
            principle="identity"
            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        tabularNums
                        align="center"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : `#${row.rank}`}
                    />
                ),
                () => (
                    <FillAvailable
                        at="base"
                        isSkeleton={isSkeleton}
                        body={({ isSkeleton: slotSkeleton }: SkeletonProps) => (
                            <UserCell
                                username={row.username}
                                avatar={row.avatar}
                                isOwnRow={row.isMe}
                                trailing={({ isSkeleton: trailingSkeleton }: SkeletonProps) => (
                                    <Typography
                                        size="sm"
                                        weight="medium"
                                        tabularNums
                                        isSkeleton={trailingSkeleton}
                                        text={trailingSkeleton ? undefined : row.valueLabel}
                                    />
                                )}
                                isSkeleton={slotSkeleton}
                            />
                        )}
                    />
                ),
                ...(row.isMe ? [() => <span className="sr-only">{meLabel}</span>] : []),
            ]}
        />
    ),
})

/**
 * Assembles the list's rows: the visible `rows`, then — only when the viewer's
 * own row isn't already among them — an ellipsis marker (skipped when the gap is
 * zero) and the pinned `selfRow` at the end.
 */
const buildListItems = (
    rows: Array<LeaderboardRow>,
    selfRow: LeaderboardRow | undefined,
    hiddenBetweenCount: number | undefined,
    meLabel: string,
    isSkeleton: boolean,
): Array<SurfaceCardListItem> => {
    const rowItems = rows.map((row) => rowItem(row, meLabel, isSkeleton))
    if (!selfRow) {
        return rowItems
    }
    const ellipsisItem: SurfaceCardListItem | null =
        hiddenBetweenCount != null && hiddenBetweenCount > 0
            ? {
                key: "ellipsis",
                content: () => (
                    <Typography
                        size="xs"
                        color="muted"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : `⋯ ${hiddenBetweenCount} more in between`}
                    />
                ),
            }
            : null
    return [...rowItems, ...(ellipsisItem ? [ellipsisItem] : []), rowItem(selfRow, meLabel, isSkeleton)]
}

/** Standing + podium + ranked rows. The block's ONE leaf/state-switch content. */
export const Board = ({ standing, podiumEntries, rows, selfRow, hiddenBetweenCount, meLabel, isSkeleton }: BoardProps) => {
    const standingLabels = standing ? (
        <StackV
            gap={1}
            isSkeleton={isSkeleton}
            items={[
                // The rank NUMBER is typed data; "Rank #N" is the block's own wording (§14d.1).
                () => (
                    <Typography
                        size="base"
                        weight="bold"
                        tabularNums
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : `Rank #${standing.rank}`}
                    />
                ),
                () => (
                    <Typography
                        size="sm"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : standing.primaryLabel}
                    />
                ),
                ...(standing.secondaryLabel ? [() => (
                    <Typography
                        size="xs"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={isSkeleton ? undefined : standing.secondaryLabel}
                    />
                )] : []),
            ]}
        />
    ) : null

    const standingCard = standing ? (
        <SurfaceCard
            body={() => (
                <StackH
                    gap={3}
                    principle="identity"
                    explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                    align="center"
                    isSkeleton={isSkeleton}
                    items={[
                        () => <IconTile icon={TrophyIcon} tone="accent" size="sm" isSkeleton={isSkeleton} />,
                        () => standingLabels,
                    ]}
                />
            )}
        />
    ) : null

    return (
        <StackV identity={{ tier: "block", component: "Board" }}
            gap={6}
            isSkeleton={isSkeleton}
            items={[
                () => standingCard,
                ...(podiumEntries.length > 0 ? [() => (
                    <Podium entries={podiumEntries} meLabel={meLabel} isSkeleton={isSkeleton} />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <SurfaceCardList
                        items={buildListItems(rows, selfRow, hiddenBetweenCount, meLabel, isSkeleton ?? false)}
                        isSkeleton={isSkeleton}
                    />
                ),
            ]}
        />
    )
}

"use client"

import React from "react"
import { AsyncContent } from "@/components/composites/async/AsyncContent"
import { Board } from "./Board"
import { Confetti } from "./Confetti"
import {
    type LeaderboardBoardProps,
    type LeaderboardPodiumEntry,
    type LeaderboardRow,
    type LeaderboardStanding,
} from "./types"

export type {
    LeaderboardStanding,
    LeaderboardPodiumEntry,
    LeaderboardRow,
    LeaderboardBoardProps,
} from "./types"

/**
 * BLOCK — `LeaderboardBoard`: the ranked board itself. See the component's own
 * file header for the full reuse contract; this file only adds the states.
 *
 * 📐 LEAF by STRUCTURE (§14d.2): loading / empty / error / how many rows / whether
 * the viewer needs pinning are all DATA — `AsyncContent`'s own branch switch
 * already reads that way — so this block has exactly ONE leaf ("Board") and five
 * states inside it, the same shape `QuizRecapList`'s single `Full` leaf uses.
 */

/** Fixed-shape placeholder rendered while {@link AsyncContentBaseProps.isLoading} — no real data exists yet. */
const LOADING_PODIUM: Array<LeaderboardPodiumEntry> = [
    { rank: 2, username: "", pointsLabel: "" },
    { rank: 1, username: "", pointsLabel: "" },
    { rank: 3, username: "", pointsLabel: "" },
]
const LOADING_ROWS: Array<LeaderboardRow> = Array.from({ length: 5 }, (_, index) => ({
    key: `loading-${index}`,
    rank: index + 4,
    username: "",
    valueLabel: "",
}))
const LOADING_STANDING: LeaderboardStanding = { rank: 0, primaryLabel: "" }

/**
 * The ranked board itself. See the file header for the reuse contract, the two
 * new internal parts, and the single-leaf/multi-state read of the async switch.
 *
 * @param props - {@link LeaderboardBoardProps}
 */
const LeaderboardBoard = ({
    isLoading,
    isEmpty,
    error,
    onRetry,
    standing,
    podiumEntries,
    rows,
    selfRow,
    hiddenBetweenCount,
    celebrateKey,
    meLabel,
    isSkeleton = false,
}: LeaderboardBoardProps) => (
    <AsyncContent
        isLoading={isLoading}
        skeleton={() => (
            <Board
                standing={LOADING_STANDING}
                podiumEntries={LOADING_PODIUM}
                rows={LOADING_ROWS}
                meLabel=""
                isSkeleton
            />
        )}
        isEmpty={isEmpty}
        emptyContent={{
            title: "The leaderboard has no one yet",
            description: "Complete a lesson to claim the first spot.",
        }}
        error={error}
        errorContent={{
            title: "Couldn't load the leaderboard",
            description: "Try again to see the latest standings.",
            onRetry,
            retryLabel: "Try again",
        }}
        content={() => (
            <>
                {/* Only the CONTENT branch celebrates — there is nothing worth confetting
                    over loading chrome, an empty board, or an error message. */}
                <Confetti celebrateKey={celebrateKey} />
                <Board
                    standing={standing}
                    podiumEntries={podiumEntries}
                    rows={rows}
                    selfRow={selfRow}
                    hiddenBetweenCount={hiddenBetweenCount}
                    meLabel={meLabel}
                    isSkeleton={isSkeleton}
                />
            </>
        )}
    />
)

export { LeaderboardBoard }

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `LeaderboardHeader` — the page-identity cluster at the top of the leaderboard
 * screen: trail, title, subtitle, nothing else. Wraps `PageHeader` in a
 * domain-named block; it carries no meta chips because rank and score live in the
 * list below. A missing subtitle is a data condition on the same three-part cluster.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface LeaderboardHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link LeaderboardHeader}. */
export interface LeaderboardHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems: Array<LeaderboardHeaderCrumb>
    /** Page title, e.g. "Leaderboard". */
    title: string
    /** One-sentence subtitle explaining what the ranking measures. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c), so the shimmer keeps the exact box of the thing it replaces.
     */
    isSkeleton?: boolean
}

/**
 * Leaderboard page identity — trail, title, subtitle. See the file header for
 * why this stays a thin sibling of `ContentHeader`/`ModuleHeader` rather than
 * the screen calling `PageHeader` directly.
 *
 * @param props - {@link LeaderboardHeaderProps}
 */
const LeaderboardHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: LeaderboardHeaderProps) => {
    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() =>
                isSkeleton || breadcrumbItems.length ? (
                    // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                    <div className="w-fit">
                        <Breadcrumbs
                            collapseOnMobile
                            collapseFrom={4}
                            items={breadcrumbItems}
                            isSkeleton={isSkeleton}
                        />
                    </div>
                ) : undefined
            }
            title={title}
            description={description}
        />
    )
}

export { LeaderboardHeader }

"use client"

import {
    BookOpenIcon,
    ListIcon,
    ListBulletsIcon,
} from "@phosphor-icons/react"
import React, { useEffect } from "react"
import { cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import { OnThisPage } from "@/components/blocks/learn/OnThisPage"
import { useTableOfContents } from "@/components/blocks/learn/OnThisPage/hooks/useTableOfContents"
import { useSidebarNavItems } from "@/hooks/useSidebarNavItems"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setMobileView, type MobileLearnView } from "@/redux/slices/sidebar"

/**
 * Mobile bottom-tab bar for the lesson reader (hidden from `lg` up).
 *
 * The desktop 4-column layout (course-nav · content-map · content · on-this-page)
 * has no room on phones, so this collapses it into an app-style bottom-tab: one
 * full-screen view at a time, thumb-reachable. Three tabs —
 *  - **Contents**: course-nav rows ({@link SidebarNavItem}) + the {@link ContentMap}
 *    lesson list (both are "navigation");
 *  - **Lesson**: the content itself (the reader is rendered by the shell — this
 *    tab just closes the overlays);
 *  - **On this page**: the {@link OnThisPage} outline (self-hides → tab omitted when
 *    the lesson has no headings).
 *
 * Selecting a new lesson lands the reader back on the content view. State lives in
 * the `sidebar` slice (`mobileView`) so the shell can mount the matching view.
 */
export const LearnMobileTabBar = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const view = useAppSelector((state) => state.sidebar.mobileView)
    const contentId = useAppSelector((state) => state.content.id)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // mirror OnThisPage's self-hide: no headings → no "on this page" tab
    const { headings } = useTableOfContents(contentId)
    const hasToc = headings.length > 0

    // opening a new lesson (from the map) lands the reader back on the content
    useEffect(() => {
        dispatch(setMobileView("content"))
    }, [contentId, dispatch])

    // never strand the user on an "On this page" tab that just vanished
    useEffect(() => {
        if (view === "toc" && !hasToc) {
            dispatch(setMobileView("content"))
        }
    }, [view, hasToc, dispatch])

    const tabs: Array<{ key: MobileLearnView; icon: typeof ListIcon; label: string }> = [
        { key: "map", icon: ListIcon, label: t("learnTabs.contents") },
        { key: "content", icon: BookOpenIcon, label: t("learnTabs.lesson") },
        ...(hasToc
            ? [{ key: "toc" as const, icon: ListBulletsIcon, label: t("learnTabs.onThisPage") }]
            : []),
    ]

    return (
        <>
            {/* full-screen "Contents" overlay — course-nav + the lesson list */}
            {view === "map" && (
                <div className="fixed top-16 bottom-16 left-0 right-[var(--app-rail-w,0px)] z-30 overflow-y-auto bg-background @app-lg:hidden">
                    <div className="flex flex-col gap-3 p-6">
                        {items.map((item) => (
                            <SidebarNavItem
                                key={item.value}
                                icon={<item.icon className="size-5 shrink-0" />}
                                label={item.label}
                                isActive={selectedTab === item.tab}
                                onPress={() => onSelect(item)}
                            />
                        ))}
                    </div>
                    <div className="border-t" />
                    <ContentMap />
                </div>
            )}

            {/* full-screen "On this page" overlay — the lesson outline + actions */}
            {view === "toc" && hasToc && (
                <div className="fixed top-16 bottom-16 left-0 right-[var(--app-rail-w,0px)] z-30 overflow-y-auto bg-background @app-lg:hidden">
                    <OnThisPage mobile />
                </div>
            )}

            {/* the bottom-tab bar itself */}
            <nav
                role="tablist"
                aria-label={t("learnTabs.contents")}
                className="fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 flex h-16 border-t bg-background/90 backdrop-blur-xl @app-lg:hidden"
            >
                {tabs.map((tab) => {
                    const isActive = view === tab.key
                    return (
                        <button
                            key={tab.key}
                            type="button"
                            role="tab"
                            aria-selected={isActive}
                            onClick={() => dispatch(setMobileView(tab.key))}
                            className={cn(
                                "flex flex-1 flex-col items-center justify-center gap-2 outline-none",
                                "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-inset",
                                isActive ? "text-accent-soft-foreground" : "text-muted",
                            )}
                        >
                            <tab.icon className="size-5" />
                            <span className="text-xs">{tab.label}</span>
                        </button>
                    )
                })}
            </nav>
        </>
    )
}

export default LearnMobileTabBar

"use client"

import React from "react"
import { Typography, cn, Separator } from "@heroui/react"
import type { MilestoneEntity } from "@/modules/types/entities/milestone"

/**
 * Props for {@link MilestoneIndexStrip}.
 */
export interface MilestoneIndexStripProps {
    /** Milestones to render, already ordered. */
    milestones: Array<MilestoneEntity>
    /** Currently active milestone id (highlights its number). */
    activeMilestoneId?: string
    /** Fired with the chosen milestone id when a number is pressed. */
    onSelectMilestone: (milestoneId: string) => void
}

/**
 * Slim numbered index of project milestones (collapsed milestone-outline rail).
 *
 * Presentational mirror of `ModuleIndexStrip`: maps each milestone to a circular
 * number button (its display order) and forwards the press as the milestone id;
 * the active milestone is highlighted. `"use client"` for the press handlers.
 * @param props - milestones, active id, and select callback
 */
export const MilestoneIndexStrip = ({
    milestones,
    activeMilestoneId,
    onSelectMilestone}: MilestoneIndexStripProps) => {
    return (
        // centered vertical stack of number chips; padded to clear the collapse bar
        <div className={"flex flex-col items-center gap-2 px-0 py-3"}>
            {milestones.map((milestone) => {
                return (
                    <React.Fragment key={String(milestone.id)}>
                        <button
                            type="button"
                            className={
                                cn(
                                    "font-semibold cursor-pointer items-center justify-center transition-colors p-2 outline-none",
                                    "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 rounded-full",
                                    String(milestone.id) === String(activeMilestoneId)
                                        ? "text-accent-soft-foreground"
                                        : "text-muted hover:text-accent-soft-foreground"
                                )
                            }
                            onClick={
                                () => onSelectMilestone(String(milestone.id))
                            }
                        >
                            <Typography type="body" className="font-semibold">
                                {milestone.sortIndex}
                            </Typography>
                        </button>
                        <Separator
                            className="w-full"
                        />
                    </React.Fragment>
                )
            })}
        </div>
    )
}

import React from "react"
import { CheckCircleIcon, ArrowRightIcon } from "@phosphor-icons/react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { StackV } from "@/components/frames/Stack"

/**
 * BLOCK — `MilestoneUpNextCard`: the passed-attempt handoff to the NEXT
 * unlocked milestone task on a capstone track. Distinct from the challenge
 * flow (no such fixed handoff exists there) — see the component file header.
 *
 * 📐 TWO LEAVES (§14d.2). `showCheck` and `isSkeleton` only toggle a glyph or
 * mirror the existing shape — neither changes what is composed, so both are
 * STATES of `Default`. `isHighlight` is different: it adds/removes the
 * highlight streak, a real DOM node, so its two values are the `Default`
 * (highlighted, the milestone screen's original shape) and `Plain` (reused by
 * `ContentPage`'s mobile/tablet nudge — see that component's file header for
 * why the default doesn't fit there) leaves.
 */

/** Props for {@link MilestoneUpNextCard}. */
export interface MilestoneUpNextCardProps {
    /** Small label above the title, e.g. "Next task". */
    eyebrow: string
    /** `true` → a check glyph sits beside the eyebrow, marking the attempt just passed. */
    showCheck?: boolean
    /** Name of the next unlocked milestone task. */
    title: string
    /** One line describing what the next task asks for. */
    description: string
    /** CTA label, e.g. "Start task 3". */
    ctaLabel: string
    /** Press the CTA. */
    onPress?: () => void
    /** `true` → the card face carries the highlight streak (the ONE focal action on its screen). @default true */
    isHighlight?: boolean
    /** `true` → every composed atom mirrors as shimmer. */
    isSkeleton?: boolean
}

/**
 * The single "what's next" highlight card shown right after a passed
 * milestone attempt, handing off to the next unlocked task on the track.
 *
 * @param props - {@link MilestoneUpNextCardProps}
 */
const MilestoneUpNextCard = ({
    eyebrow,
    showCheck = false,
    title,
    description,
    ctaLabel,
    onPress,
    isHighlight = true,
    isSkeleton = false,
}: MilestoneUpNextCardProps) => (
    <SurfaceCard
        identity={{ tier: "block", component: "MilestoneUpNextCard" }}
        isHighlight={isHighlight}
        isSkeleton={isSkeleton}
        body={() => (
            <StackV
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    // Back INSIDE the card face (not `SurfaceCard.label`,
                    // which sits OUTSIDE/above it) — a plain atom call, not raw CSS, so no
                    // shape-tier violation either way; this is a visual placement call.
                    () => (
                        <Typography
                            size="xs"
                            color="muted"
                            prefixIcon={showCheck ? CheckCircleIcon : undefined}
                            isSkeleton={isSkeleton}
                            text={eyebrow}

                        />
                    ),
                    // Real `UpNextCard` leaves `type` unset on its title
                    // Typography, which defaults to HeroUI's `type="body"` = `text-base`
                    // (verify `typography.css` `.typography--body`). `weight="semibold"`
                    // folds to `"medium"` at body
                    // scale, not `"bold"`.
                    () => (
                        <Typography
                            size="base"
                            weight="medium"
                            isSkeleton={isSkeleton}
                            text={title}

                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            color="muted"
                            isSkeleton={isSkeleton}
                            text={description}

                        />
                    ),
                    () => (
                        <Button
                            isSkeleton={isSkeleton}
                            variant="primary"
                            size="sm"
                            label={ctaLabel}
                            suffixIcon={ArrowRightIcon}
                            iconSlide
                            onPress={onPress}
                            classNames={["w-fit", "shrink-0"]}

                        />
                    ),
                ]}
            />
        )}
    />
)

export { MilestoneUpNextCard }

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { ArrowRightIcon, CheckCircleIcon, WarningCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { SurfaceCard, SurfaceCardCrossList, type SurfaceCardCrossListItem } from "@/components/composites/cards/SurfaceCard"
import { Callout, type CalloutIcon } from "@/components/composites/feedback/Callout"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { StackH, StackV } from "@/components/frames/Stack"
import { ScoreRow } from "./ScoreRow"

/**
 * `MockInterviewScorecard` — read-only render of one graded mock-interview run:
 * a verdict banner (`Callout`), hand-laid `ProgressMeter` rows for the score and
 * attribute breakdowns, and strengths/gaps via `SurfaceCard.CrossList`. Every
 * optional section — byline, attribute breakdown, strengths, gaps, follow-up,
 * weak-area tag, retry — is a state of one shape. Per-question model-answer review
 * is out of scope (no primitive for it yet).
 */

/** Pass / borderline / fail — reuses the interview verdict vocabulary verbatim from the BE contract. */
export type MockInterviewVerdict = "pass" | "borderline" | "fail"

/** One row of the score breakdown — a phase (design mode) or a question ordinal (Q&A mode), already display-labeled by the caller. */
export interface MockInterviewScoreRow {
    /** Stable React key. */
    key: string
    /** Display label — a resolved phase name or a question ordinal ("Question 1"), already localized/resolved by the caller. */
    label: string
    /** Points earned for this phase/question. */
    score: number
    /** Points available for this phase/question. */
    max: number
}

/** One row of the attribute breakdown (communication, structured thinking …), 0–100. */
export interface MockInterviewAttributeScoreRow {
    /** Stable React key. */
    key: string
    /** Display label, already localized/resolved by the caller. */
    label: string
    /** 0–100. */
    score: number
}

/** Props for {@link MockInterviewScorecard}. */
export interface MockInterviewScorecardProps {
    /** Pass / borderline / fail — drives the verdict callout's tone, icon and wording. */
    verdict: MockInterviewVerdict
    /** Overall score, 0–100. */
    overallScore: number
    /** Per-phase or per-question score breakdown, in display order. Section self-hides when empty (and `isSkeleton` is off). */
    phaseOrQuestionScores: Array<MockInterviewScoreRow>
    /** Per-attribute score breakdown, in display order. Section self-hides when empty. */
    attributeScores: Array<MockInterviewAttributeScoreRow>
    /** Concrete things done right, as markdown. Section self-hides when empty. */
    strengths: Array<string>
    /** Concrete gaps framed as "what to add", as markdown. Section self-hides when empty. */
    gaps: Array<string>
    /** A follow-up an interviewer would ask next, as markdown. Omit -> the section does not render. */
    followUpQuestion?: string | null
    /** The weakest area, already resolved by the caller (which phase/attribute counts as "weak enough to push" is a screen-level call, not this block's). Omit -> the primary CTA reads generically. */
    weakAreaLabel?: string
    /** Fired when the learner takes the primary CTA — go study the weak area. */
    onStudyWeakArea: () => void
    /** Fired when the learner picks the capstone hand-off CTA. */
    onCapstone: () => void
    /** Fired when the learner wants to run the interview again. Omit -> the retry action does not render (e.g. a read-only history detail). */
    onRetry?: () => void
    /** The system/prompt this run interviewed on, shown as a header line when known. */
    promptTitle?: string
    /** When this attempt was graded, already formatted/localized by the caller (e.g. "Jul 28, 2026 · 14:32"). Omit for a live, just-finished session. */
    createdAt?: string
    /** `true` -> every part this block renders itself mirrors as shimmer. */
    isSkeleton?: boolean
}

/** Verdict -> callout tone. */
const VERDICT_STATUS: Record<MockInterviewVerdict, "success" | "warning" | "danger"> = {
    pass: "success",
    borderline: "warning",
    fail: "danger",
}

/** Verdict -> callout indicator icon. */
const VERDICT_ICON: Record<MockInterviewVerdict, CalloutIcon> = {
    pass: CheckCircleIcon,
    borderline: WarningCircleIcon,
    fail: XCircleIcon,
}

/** Verdict -> the block's own wording (§14d.1 — a caller passes the enum, never a formatted string). */
const VERDICT_LABEL: Record<MockInterviewVerdict, string> = {
    pass: "Pass",
    borderline: "Borderline",
    fail: "Fail",
}

/** Placeholder row count while `isSkeleton` and the real breakdown length isn't known yet. */
const SKELETON_SCORE_ROWS = 3
const SKELETON_ATTRIBUTE_ROWS = 3

/**
 * The graded-run scorecard. See the file header for the full contract, the
 * scope cut (no per-question review this pass), and why every optional
 * section stays a STATE of this one leaf.
 *
 * @param props - {@link MockInterviewScorecardProps}
 */
const MockInterviewScorecard = ({
    verdict,
    overallScore,
    phaseOrQuestionScores,
    attributeScores,
    strengths,
    gaps,
    followUpQuestion,
    weakAreaLabel,
    onStudyWeakArea,
    onCapstone,
    onRetry,
    promptTitle,
    createdAt,
    isSkeleton = false,
}: MockInterviewScorecardProps) => {
    const hasByline = isSkeleton || promptTitle != null || createdAt != null
    const hasScoreRows = isSkeleton || phaseOrQuestionScores.length > 0
    const hasAttributeRows = isSkeleton || attributeScores.length > 0
    const hasStrengths = isSkeleton || strengths.length > 0
    const hasGaps = isSkeleton || gaps.length > 0
    const hasFollowUp = isSkeleton || Boolean(followUpQuestion)

    const strengthItems: Array<SurfaceCardCrossListItem> = strengths.map((strength, index) => ({
        key: `strength-${index}`,
        mark: "check",
        tone: "success",
        text: strength,
    }))

    const gapItems: Array<SurfaceCardCrossListItem> = gaps.map((gap, index) => ({
        key: `gap-${index}`,
        mark: "cross",
        tone: "danger",
        text: gap,
    }))

    const primaryCtaLabel = weakAreaLabel ? `Review: ${weakAreaLabel}` : "Review your weak areas"

    const bylineRow = hasByline ? (
        <StackH
            gap={4}
            justify="between"
            at="sm"
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            isSkeleton={isSkeleton}
            items={[
                () => (isSkeleton ? (
                    <Typography size="sm" weight="medium" isSkeleton />
                ) : promptTitle != null ? (
                    <Typography size="sm" weight="medium" text={promptTitle} />
                ) : null),
                () => (isSkeleton ? (
                    <Typography size="xs" color="muted" isSkeleton classNames={["w-1/3"]} />
                ) : createdAt != null ? (
                    <Typography size="xs" color="muted" text={createdAt} />
                ) : null),
            ]}
        />
    ) : null

    const scoreBreakdownBody = (
        <>
            {(isSkeleton
                ? Array.from({ length: SKELETON_SCORE_ROWS }, (_, index) => ({
                    key: `score-skeleton-${index}`,
                    label: "",
                    score: 0,
                    max: 100,
                }))
                : phaseOrQuestionScores
            ).map((row) => (
                <ScoreRow
                    key={row.key}
                    label={row.label}
                    score={row.score}
                    max={row.max}
                    isSkeleton={isSkeleton}
                />
            ))}
        </>
    )

    const attributeBreakdownBody = (
        <>
            {(isSkeleton
                ? Array.from({ length: SKELETON_ATTRIBUTE_ROWS }, (_, index) => ({
                    key: `attribute-skeleton-${index}`,
                    label: "",
                    score: 0,
                    max: 100,
                }))
                : attributeScores.map((row) => ({ ...row, max: 100 }))
            ).map((row) => (
                <ScoreRow
                    key={row.key}
                    label={row.label}
                    score={row.score}
                    max={row.max}
                    isSkeleton={isSkeleton}
                />
            ))}
        </>
    )

    const strengthsBody = (
        <>
            <Typography size="sm" weight="medium" text="Strengths" />
            <SurfaceCardCrossList items={strengthItems} isSkeleton={isSkeleton} />
        </>
    )

    const gapsBody = (
        <>
            <Typography size="sm" weight="medium" text="Areas to improve" />
            <SurfaceCardCrossList items={gapItems} isSkeleton={isSkeleton} />
        </>
    )

    const weakAreaRow = weakAreaLabel != null && !isSkeleton ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text="Weakest:" isSkeleton={isSkeleton} />,
                ({ isSkeleton }: SkeletonProps) => <Chip tone="warning" text={weakAreaLabel} isSkeleton={isSkeleton} />,
            ]}
        />
    ) : null

    const ctaButtonRow = (
        <StackH
            gap={4}
            at="sm"
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="primary"
                        size="lg"
                        label={primaryCtaLabel}
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onStudyWeakArea}

                    />
                ),
                () => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="lg"
                        label="Work on personal project"
                        onPress={onCapstone}

                    />
                ),
                ...(onRetry != null || isSkeleton ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="ghost"
                        size="lg"
                        label="Retry interview"
                        onPress={onRetry}

                    />
                )] : []),
            ]}
        />
    )

    const ctaSection = (
        <>
            {weakAreaRow}
            {ctaButtonRow}
        </>
    )

    const scorecardBody = (
        <>
            {bylineRow}

            {/* Verdict banner. `Callout` has no `isSkeleton` of its own (a message
 frame, not a data-bearing one) — a bare bar stands in, in the same slot. */}
            {isSkeleton ? (
                <Skeleton className="h-20 w-full rounded-2xl" />
            ) : (
                <Callout
                    status={VERDICT_STATUS[verdict]}
                    icon={VERDICT_ICON[verdict]}
                    title={`${overallScore}/100 · ${VERDICT_LABEL[verdict]}`}

                />
            )}

            {hasScoreRows ? (
                <SurfaceCard
                    label="Score by section"


                    body={() => <StackV gap={4} isSkeleton={isSkeleton} items={[() => scoreBreakdownBody]} />}
                />
            ) : null}

            {hasAttributeRows ? (
                <SurfaceCard
                    label="Score by criterion"


                    body={() => <StackV gap={4} isSkeleton={isSkeleton} items={[() => attributeBreakdownBody]} />}
                />
            ) : null}

            {hasStrengths ? (
                <StackV gap={3} isSkeleton={isSkeleton} items={[() => strengthsBody]} />
            ) : null}

            {hasGaps ? (
                <StackV gap={3} isSkeleton={isSkeleton} items={[() => gapsBody]} />
            ) : null}

            {/* no icon here — §5a.2: a chat-bubble needs an ASSOCIATION step to read as
 "a question" (not a universal symbol like [ok]/(locked)), and the card's own
 label="Follow-up question" already carries the fact. */}
            {hasFollowUp ? (
                <SurfaceCard
                    label="Follow-up question"


                    body={() => (
                        <MarkdownContent
                            source={followUpQuestion ?? ""}
                            measure="compact"
                            flow="embedded"
                            emphasis="italic"
                            isSkeleton={isSkeleton}
                        />
                    )}
                />
            ) : null}

            <StackV gap={3} isSkeleton={isSkeleton} items={[() => ctaSection]} />
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => scorecardBody]} />
        </div>
    )
}

export { MockInterviewScorecard }

import React from "react"
import { ClockIcon, PuzzlePieceIcon, StackIcon } from "@phosphor-icons/react"
import { CourseContentTier } from "@/modules/types/enums/course-content-tier"
import { Chip } from "@/components/atoms/chips/Chip"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { HighlightChip } from "@/components/composites/chips/HighlightChip"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH } from "@/components/frames/Stack"

/**
 * `ModuleHeader` — the module-identity cluster at the top of a module's page,
 * answering "what is this module, and how big is it". Sibling of `ContentHeader`
 * and `CourseBrief`: places identity into `PageHeader`, but carries a module's tier
 * plus three `HighlightChip` counts (lessons, minutes, challenges) — the counts are
 * the headline figures, so they keep their chip shape while `tier` classifies the
 * module. Which chips draw stays states of one shape; losing the whole meta row
 * drops a `PageHeader` region and earns its own shape.
 */

/** Tier → chip presentation. The block owns this table (§14d.1: no caller-supplied color/label). */
const TIER_MAP: Record<CourseContentTier, EnumChipEntry> = {
    [CourseContentTier.Foundation]: { color: "success", label: "Foundation" },
    [CourseContentTier.Intermediate]: { color: "warning", label: "Intermediate" },
    [CourseContentTier.Advanced]: { color: "danger", label: "Advanced" },
}

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface ModuleHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link ModuleHeader}. */
export interface ModuleHeaderProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. A module is always reached through its course, so the trail is always required (no "no breadcrumb" case, same call `ContentHeader` makes). */
    breadcrumbItems: Array<ModuleHeaderCrumb>
    /** Module title. */
    title: string
    /** One-sentence summary of the module. */
    description?: string
    /** Learning tier — the ONE classifying fact, drives the `EnumChip` tone + label. Omit → no tier chip. */
    tier?: CourseContentTier
    /** How many lessons this module has — the block adds "lessons" itself. Omit or `0` → no chip. */
    lessonCount?: number
    /** Total reading/study minutes across the module — the block adds "minutes of study" itself. Omit or `0` → no chip. */
    minutesTotal?: number
    /** How many challenges hang off this module — the block adds "challenges" itself. Omit or `0` → no chip. */
    challengeCount?: number
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The module identity cluster at the top of a module's own page. See the file
 * header for the full contract and why this is a sibling of `ContentHeader`/
 * `CourseBrief` rather than an edit of either.
 *
 * @param props - {@link ModuleHeaderProps}
 */
const ModuleHeader = ({
    breadcrumbItems,
    title,
    description,
    tier,
    lessonCount,
    minutesTotal,
    challengeCount,
    isSkeleton = false,
}: ModuleHeaderProps) => {
    const hasLessons = (lessonCount ?? 0) > 0
    const hasMinutes = (minutesTotal ?? 0) > 0
    const hasChallenges = (challengeCount ?? 0) > 0
    // The meta row only exists once it has something to show — otherwise `PageHeader`
    // gets `undefined` and drops the whole slot instead of an empty row with nothing in it.
    const hasMeta = isSkeleton || tier != null || hasLessons || hasMinutes || hasChallenges

    const metaRow = hasMeta ? (
        <StackH
            gap={3}
            align="center"
            at="sm"
            principle="chip-row"
            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
            isSkeleton={isSkeleton}

            items={[
                () => (isSkeleton ? (
                    <EnumChip
                        value={CourseContentTier.Foundation}
                        map={TIER_MAP}
                        isSkeleton

                    />
                ) : tier != null ? (
                    <EnumChip value={tier} map={TIER_MAP} />
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={StackIcon} />
                    </span>
                ) : hasLessons ? (
                    <span>
                        <HighlightChip
                            icon={StackIcon}
                            value={lessonCount}
                            label="lessons"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={ClockIcon} />
                    </span>
                ) : hasMinutes ? (
                    <span>
                        <HighlightChip
                            icon={ClockIcon}
                            value={minutesTotal}
                            label="minutes"
                        />
                    </span>
                ) : null),
                () => (isSkeleton ? (
                    <span>
                        <Chip isSkeleton icon={PuzzlePieceIcon} />
                    </span>
                ) : hasChallenges ? (
                    <span>
                        <HighlightChip
                            icon={PuzzlePieceIcon}
                            value={challengeCount}
                            label="challenges"
                        />
                    </span>
                ) : null),
            ]}
        />
    ) : undefined

    return (
        // Identity hold: PageHeader does not accept CallerIdentity (ledger PageHeader gap).
        <PageHeader
            isSkeleton={isSkeleton}
            breadcrumb={() => (
                // Hold: no hug-width frame for breadcrumb measure (`w-fit` parent placement).
                <div className="w-fit">
                    <Breadcrumbs
                        collapseOnMobile
                        collapseFrom={4}
                        items={breadcrumbItems}
                        isSkeleton={isSkeleton}
                    />
                </div>
            )}
            title={title}
            description={description}
            meta={() => metaRow}
        />
    )
}

export { ModuleHeader }

"use client"

import React from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { useQuerySearchCourseContentSwr } from "@/hooks/swr/api/graphql/queries/useQuerySearchCourseContentSwr"
import { LabeledList } from "@/components/blocks/lists/LabeledList"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"

/** Placeholder deck rows shown while the RAG search is in flight. */
const SKELETON_ROWS = 3

/**
 * Right-rail "review this lesson" panel: flashcard decks RAG-related to the
 * lesson currently being read (`searchCourseContent`, filtered to
 * `kind: "flashcard"` — the `flashcard_deck_contents` M2M this used to read
 * from was dropped; deck↔lesson association is RAG-derived now, same as
 * `RelatedContentList`), with a primary CTA into the Flashcards page to start
 * a spaced-repetition session.
 *
 * Reads the active course + content title from Redux and self-hides once the
 * search settles with no related decks, so it never leaves an empty box in the
 * rail. The label and the CTA are static i18n — known before the search returns —
 * so only the DECK ROWS shimmer, inside the same `LabeledList` the loaded rows
 * use (`loading-and-skeleton.md`).
 */
export const LessonFlashcards = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const contentTitle = useAppSelector((state) => state.content.entity?.title)

    const swr = useQuerySearchCourseContentSwr(
        courseId ?? null,
        contentTitle ?? "",
        Boolean(courseId && contentTitle),
    )

    // dedupe by deck — the RAG search can surface several cards from the same deck
    const decks = Array.from(
        new Map(
            (swr.data ?? [])
                .filter((item) => item.kind === "flashcard" && item.deckId)
                .map((item) => [item.deckId as string, { id: item.deckId as string, title: item.title }]),
        ).values(),
    )

    // open the Flashcards page for this course (deck is chosen there)
    const onReview = () => {
        if (!courseDisplayId) {
            return
        }
        router.push(
            pathConfig().locale(locale).course(courseDisplayId).learn().flashcards().build(),
        )
    }

    const isSkeleton = swr.isLoading
    // settled with nothing related → the panel self-hides rather than showing an empty box
    if (!isSkeleton && decks.length === 0) {
        return null
    }

    return (
        <LabeledList
            label={t("lessonRail.flashcards.title")}
            action={(
                <Button
                    label={t("lessonRail.flashcards.review")}
                    size="sm"
                    variant="secondary"
                    onPress={onReview}
                />
            )}
        >
            {isSkeleton
                ? Array.from({ length: SKELETON_ROWS }, (_row, index) => (
                    <Typography key={index} size="sm" color="muted" isSkeleton />
                ))
                : decks.map((deck) => (
                    <Typography key={deck.id} size="sm" color="muted" truncate text={deck.title} />
                ))}
        </LabeledList>
    )
}

import React from "react"
import { CircleIcon } from "@phosphor-icons/react"
import { ContinueCardHero } from "@/components/blocks/learn/ContinueCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"

/**
 * `PersonalProjectGatePreview` — the capstone teaser dropped into `EnrollGate`'s
 * `preview` slot inside `LearnShell`: what a trial viewer sees of the
 * personal-project workspace, behind the gate's fade/lock. Composes
 * `ContinueCardHero` for the headline, a standalone `ProgressMeter` for capstone
 * completion, and `SurfaceCard` with a `label`. Non-interactive — the fade/lock
 * affordance belongs to `EnrollGate`. Task count and names are data on one shape.
 */

/** One milestone-0 task title shown in the teaser's task list. */
export interface PersonalProjectGatePreviewTask {
    /** Task title. */
    title: string
}

/**
 * Capstone overall completion fed to the standalone `ProgressMeter` (see file
 * header for why this stays a separate meter from `ContinueCardHero`'s own bar).
 */
export interface ProgressMeterData {
    /** Current progress value. Should fall within `[0, max]`. */
    value: number
    /** The 100% mark. Defaults to `100` (`ProgressMeter`'s own default). */
    max?: number
    /** Label rendered above the bar, e.g. "Personal project progress". */
    label?: string
}

/** Section label the block owns itself — see file header. */
const TASK_LABEL = "Milestone 0 Tasks"

/** Props for {@link PersonalProjectGatePreview}. */
export interface PersonalProjectGatePreviewProps {
    /** Capstone project name/headline — becomes `ContinueCardHero`'s title. */
    heroTitle: string
    /** One-line pitch under the headline — becomes `ContinueCardHero`'s subtitle. */
    heroSubtitle: string
    /** The capstone's overall completion, shown in its own `ProgressMeter`. */
    progress: ProgressMeterData
    /** Milestone-0 task titles, in display order. */
    items: Array<PersonalProjectGatePreviewTask>
    /**
     * `true` → every composed leaf draws its own shimmer mirror instead of the
     * real content. Flows straight into `ContinueCardHero`, `SurfaceCard`, and
     * each task row's `Typography` (§12c) — no parallel skeleton tree built here.
     */
    isSkeleton?: boolean
}

/**
 * The capstone teaser dropped behind `EnrollGate`'s fade. See the file header
 * for the full contract.
 *
 * @param props - {@link PersonalProjectGatePreviewProps}
 */
const PersonalProjectGatePreview = ({
    heroTitle,
    heroSubtitle,
    progress,
    items,
    isSkeleton = false,
}: PersonalProjectGatePreviewProps) => {
    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderTaskRow = (item: PersonalProjectGatePreviewTask, index: number) => (
        <StackH
            key={index}
            gap={2}
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            align="center"
            isSkeleton={isSkeleton}

            items={[
                () => <CircleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-muted" />,
                () => (
                    <Typography
                        size="sm"
                        truncate
                        isSkeleton={isSkeleton}
                        text={item.title}

                    />
                ),
            ]}
        />
    )

    const taskList = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}

            items={items.map((item, index) => () => renderTaskRow(item, index))}
        />
    )

    return (
        <StackV identity={{ tier: "block", component: "PersonalProjectGatePreview" }}
            gap={6}
            isSkeleton={isSkeleton}

            items={[
                () => (
                    <ContinueCardHero
                        title={heroTitle}
                        subtitle={heroSubtitle}
                        isSkeleton={isSkeleton}


                    />
                ),
                () => (
                    <ProgressMeter
                        value={progress.value}
                        max={progress.max}
                        label={progress.label}
                        showValue


                    />
                ),
                () => (
                    <SurfaceCard
                        label={TASK_LABEL}
                        isSkeleton={isSkeleton}


                        body={() => taskList}
                    />
                ),
            ]}
        />
    )
}

export { PersonalProjectGatePreview }

import React from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { ArrowClockwiseIcon, CaretDownIcon, CaretUpIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip, type ChipTone } from "@/components/atoms/chips/Chip"
import { Typography, type TypographyColor } from "@/components/atoms/text/Typography"
import { StatRibbon, type StatRibbonItem } from "@/components/composites/stats/StatRibbon"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK — `PlaygroundConnectSheet`: the docked connection console under the lab
 * canvas — a peek row (status + reconnect) that never leaves the screen, and a
 * body the learner opens to see device specs and the live agent log.
 *
 * ONE LEAF, THREE DATA STATES (see the component's file header for the full
 * reasoning): `connected` shows the real device panel, `waiting` and `dropped`
 * share the same not-connected hint body and differ only in the peek chip's
 * wording/tone — `dropped` cannot happen without a prior connection, so no
 * extra `everConnected` prop is needed to tell the two apart.
 */

/** How the lab's device pairing currently stands. */
export type PlaygroundConnectionState = "connected" | "waiting" | "dropped"

/** One line the local agent printed, already leveled by the caller. */
export type PlaygroundAgentLogLevel = "info" | "success" | "warn" | "error"

/** The learner's machine, as reported by the connected agent. */
export interface PlaygroundDeviceSpec {
    /** e.g. `"Windows"`, `"macOS"`, `"Linux"`. */
    platform: string
    /** e.g. `"x64"`, `"arm64"`. */
    arch: string
    hostname: string
    cpuCores: number
    cpuModel: string
    totalMemBytes: number
    freeMemBytes: number
    /** Omitted → the machine has no discrete GPU the agent could report. */
    gpu?: string
    vramTotalMb?: number
    vramFreeMb?: number
}

/** One printed line from the local agent's live log. */
export interface PlaygroundAgentLogLine {
    level: PlaygroundAgentLogLevel
    line: string
}

interface PlaygroundConnectSheetOwnProps {
    /** Round-trip time to the local agent. Only shown while `connection === "connected"`. */
    latencyMs?: number
    /**
     * The paired machine's specs. Present only once the agent has reported at
     * least once — its presence is how `"dropped"` differs from `"waiting"` in
     * spirit, even though both render the same hint body (see file header).
     */
    device?: PlaygroundDeviceSpec
    /** Fired when the learner presses the peek row's reconnect action. */
    onReconnect: () => void
    /** Whether the body (device specs + log, or the hint) is expanded. Controlled. */
    open: boolean
    /** Fired with the next expanded state when the learner presses the toggle. */
    onOpenChange: (open: boolean) => void
}

/**
 * Props for {@link PlaygroundConnectSheet}. `connection`/`agentLog` are
 * REQUIRED unless `isSkeleton` (§12b) — the pairing state itself hasn't
 * resolved yet on first mount.
 */
export type PlaygroundConnectSheetProps = PlaygroundConnectSheetOwnProps &
    (
        | { isSkeleton: true; connection?: PlaygroundConnectionState; agentLog?: Array<PlaygroundAgentLogLine> }
        | {
            isSkeleton?: false
            /** Current pairing state — drives the peek chip's tone and wording. */
            connection: PlaygroundConnectionState
            /** Live tail of the local agent's log, oldest first. Shown only while connected. */
            agentLog: Array<PlaygroundAgentLogLine>
        }
    )

const STATUS_TONE: Record<PlaygroundConnectionState, ChipTone> = {
    connected: "success",
    waiting: "warning",
    dropped: "danger",
}

const STATUS_DOT_CLASS: Record<PlaygroundConnectionState, string> = {
    connected: "text-success",
    waiting: "text-warning",
    dropped: "text-danger",
}

/** The block owns this vocabulary — the caller only ever hands over the enum. */
const STATUS_LABEL: Record<PlaygroundConnectionState, string> = {
    connected: "Connected",
    waiting: "Waiting to connect",
    dropped: "Disconnected",
}

const LOG_COLOR: Record<PlaygroundAgentLogLevel, TypographyColor> = {
    info: "muted",
    success: "success",
    warn: "warning",
    error: "danger",
}

/** Same hint for both not-connected states — see file header on `waiting` vs `dropped`. */
const NOT_CONNECTED_HINT =
    "Turn on the agent on your machine, then press Reconnect. Your device specs and log will show up here as soon as the connection is back."

/** `1 234 567 890` → `"1.1 GB"` / `"48 MB"` — the block owns this wording, not a shared util (one call site). */
const formatBytes = (bytes: number): string => {
    const GIB = 1024 ** 3
    if (bytes >= GIB) return `${(bytes / GIB).toFixed(1)} GB`
    return `${Math.round(bytes / 1024 ** 2)} MB`
}

/** Device spec → the 3–4 {@link StatRibbon} cells, GPU cell only when the machine reports one. */
const buildDeviceItems = (device: PlaygroundDeviceSpec): Array<StatRibbonItem> => {
    const items: Array<StatRibbonItem> = [
        { key: "host", value: device.hostname, label: `${device.platform} · ${device.arch}` },
        { key: "cpu", value: `${device.cpuCores} cores`, label: device.cpuModel },
        {
            key: "ram",
            value: `${formatBytes(device.freeMemBytes)} / ${formatBytes(device.totalMemBytes)}`,
            label: "RAM free / total",
        },
    ]
    if (device.gpu != null) {
        items.push({
            key: "gpu",
            value: device.gpu,
            label:
                device.vramTotalMb != null
                    ? `VRAM ${device.vramFreeMb != null ? `${device.vramFreeMb} / ` : ""}${device.vramTotalMb} MB`
                    : "GPU",
        })
    }
    return items
}

/**
 * The docked connection console. See the file header for the reuse check and
 * the judgement calls (no new composite file, scope-disciplined toggle instead
 * of drag-resize, shared not-connected hint).
 *
 * @param props - {@link PlaygroundConnectSheetProps}
 */
const PlaygroundConnectSheet = ({
    connection,
    latencyMs,
    device,
    agentLog,
    onReconnect,
    open,
    onOpenChange,
    isSkeleton = false,
}: PlaygroundConnectSheetProps) => {
    if (isSkeleton) {
        return (
            <div className="overflow-hidden rounded-t-3xl border border-default bg-surface shadow-surface">
                <StackH
                    gap={4}
                    principle="cell-pad"
                    explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                    padding={4}
                    isSkeleton={isSkeleton}
                    body={() => (
                        <StackH
                            gap={4}
                            principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            align="center"
                            justify="between"
                            isSkeleton={isSkeleton}
                            items={[
                                () => <Skeleton className="h-5 w-24 rounded-full" />,
                                () => <Skeleton className="h-8 w-24 rounded-xl" />,
                            ]}
                        />
                    )}
                />
            </div>
        )
    }
    // `connection` is REQUIRED whenever `isSkeleton` is false (the discriminated union
    // above, already guaranteed by the early return) — the fallback only satisfies
    // narrowing across the destructure, it never actually fires.
    const safeConnection = connection ?? "waiting"
    const isConnected = safeConnection === "connected"
    const showDeviceBody = isConnected && device != null

    const statusGroup = (
        <StackH
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Chip
                        tone={STATUS_TONE[safeConnection]}
                        dotClassName={STATUS_DOT_CLASS[safeConnection]}
                        text={STATUS_LABEL[safeConnection]}
                        isSkeleton={isSkeleton}
                    />
                ),
                ...(isConnected && latencyMs != null ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        tabularNums
                        isSkeleton={isSkeleton}
                        text={`${latencyMs} ms`}

                    />
                )] : []),
            ]}
        />
    )

    const actionsGroup = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            align="center"
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Button
                        label="Reconnect"
                        variant="secondary"
                        size="sm"
                        prefixIcon={ArrowClockwiseIcon}
                        onPress={onReconnect}
                        isSkeleton={isSkeleton}
                    />
                ),
                () => (
                    <Button
                        isIconOnly
                        size="sm"
                        variant="ghost"
                        prefixIcon={open ? CaretUpIcon : CaretDownIcon}
                        ariaLabel={open ? "Collapse connection panel" : "Expand connection panel"}
                        onPress={() => onOpenChange(!open)}
                        isSkeleton={isSkeleton}
                    />
                ),
            ]}
        />
    )

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderLogLine = (entry: PlaygroundAgentLogLine) => (
        <Typography
            size="xs"
            color={LOG_COLOR[entry.level]}
            tabularNums={false}
            text={entry.line}

        />
    )

    const sheetBody = showDeviceBody ? (
        <>
            <div>
                <StatRibbon items={buildDeviceItems(device)} valueType="body" bordered />
            </div>
            <StackV gap={2} isSkeleton={isSkeleton} items={(agentLog ?? []).map((entry) => () => renderLogLine(entry))} />
        </>
    ) : (
        <Typography size="sm" color="muted" text={NOT_CONNECTED_HINT} />
    )

    return (
        <div className="overflow-hidden rounded-t-3xl border border-default bg-surface shadow-surface">
            {/* PEEK — always visible: status + reconnect, plus the toggle that opens the body. */}
            <StackH
                gap={4}
                principle="cell-pad"
                explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                padding={4}
                isSkeleton={isSkeleton}
                body={() => (
                    <StackH
                        gap={4}
                        principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        align="center"
                        justify="between"
                        isSkeleton={isSkeleton}
                        items={[
                            () => statusGroup,
                            () => actionsGroup,
                        ]}
                    />
                )}
            />
            {/* BODY — mounted only while open, matching a real bottom-sheet's collapsed state. */}
            {open ? (
                <div className="border-t border-default">
                    <StackV gap={4} principle="cell-pad"
                        explain="Tight cell inset — not card-padding, because this sits inside a dense table or list cell rather than a card body."
                        padding={4} isSkeleton={isSkeleton} body={() => (
                            <StackV gap={4} principle="card-caption"
                                explain="Holds caption text under card media so the caption stays attached to the image above it."
                                isSkeleton={isSkeleton} items={[() => sheetBody]}  />
                        )} />
                </div>
            ) : null}
        </div>
    )
}

export { PlaygroundConnectSheet }

import React from "react"
import { ArrowRightIcon, ListChecksIcon, TerminalWindowIcon } from "@phosphor-icons/react"
import { SurfaceCardPressableGroup, type SurfaceCardPressableGroupItem } from "@/components/composites/cards/SurfaceCard"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { IconTile } from "@/components/atoms/display/IconTile"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * `PlaygroundExerciseGrid` — the core of the Playground hub screen: a grid of
 * hands-on exercises the learner opens one of. Wraps `SurfaceCardPressableGroup`;
 * the cue row at the bottom of each tile stays decorative text, not a nested button.
 * Two shapes: `Default` (a bounded press-target grid of real tiles, or the
 * composite's own tile mirror while loading) and `Empty` (the grid replaced by
 * `EmptyState` when the course has no Playground exercises).
 */

/** One hands-on exercise offered by the course. */
export interface PlaygroundExerciseGridItem {
    /** Stable id — also what `onSelect` fires with. */
    id: string
    /** Display title of the exercise. */
    title: string
    /** Number of guided steps in the exercise. */
    stepCount: number
}

/** Props for {@link PlaygroundExerciseGrid}. */
export interface PlaygroundExerciseGridProps {
    /** The course's exercises, in display order. */
    exercises: Array<PlaygroundExerciseGridItem>
    /** Fired with an exercise's id on tile press. */
    onSelect: (id: string) => void
    /**
     * Accessible name for the tile grid — REQUIRED. Without it a screen reader
     * hears N loose press targets with nothing tying them together.
     */
    ariaLabel: string
    /**
     * `true` → the grid draws its own tile mirror (via the composite's generic
     * skeleton tile). `exercises` empty while loading (§12c) → guesses 4
     * tiles, this block's own SSOT convention (see file header).
     */
    isSkeleton?: boolean
}

/** Step-count wording — the block's own vocabulary (§14d.1: a block owns its wording). */
const stepCountLabel = (count: number) => `${count} steps`

/** The closing affordance cue — decorative, never its own press target (see file header, judgement 3). */
const CUE_LABEL = "Enter playground"

/** The library-itself-is-empty wording — this course has no Playground exercises at all. */
const EMPTY_TITLE = "No hands-on exercises yet"
const EMPTY_DESCRIPTION = "This course has no Playground exercise yet — check back later."

/** Guessed placeholder rows for the first fetch (§12c), mirroring `FoundationCategoryList`'s convention. */
const SKELETON_EXERCISES: Array<PlaygroundExerciseGridItem> = Array.from({ length: 4 }, (_unused, index) => ({
    id: `skeleton-${index}`,
    title: "",
    stepCount: 0,
}))

/**
 * The Playground hub's browse-and-open grid. See the file header for why the
 * icon is fixed, why the cue row stays decorative, and why the empty branch
 * lives here rather than in a separate top-level block.
 *
 * @param props - {@link PlaygroundExerciseGridProps}
 */
const PlaygroundExerciseGrid = ({
    exercises,
    onSelect,
    ariaLabel,
    isSkeleton = false,
}: PlaygroundExerciseGridProps) => {
    // Empty while loading (no real exercise yet) → guess 4 tiles, keeping the
    // right shape for when real data lands (§8). Once real `exercises` exist,
    // keep the EXACT tile count already there.
    const usingPlaceholders = isSkeleton && exercises.length === 0
    const source = usingPlaceholders ? SKELETON_EXERCISES : exercises

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderExerciseContent = (exercise: PlaygroundExerciseGridItem) => {
        const titleAndSteps = (
            <StackV
                gap={2}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <div>
                            <Typography size="base" weight="bold" truncate text={exercise.title} />
                        </div>
                    ),
                    () => (
                        <div>
                            <Chip tone="default" icon={ListChecksIcon} text={stepCountLabel(exercise.stepCount)} classNames={["w-fit"]} />
                        </div>
                    ),
                ]}
            />
        )

        return (
            <StackV
                gap={4}
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <div>
                            <IconTile icon={TerminalWindowIcon} tone="accent" size="lg" />
                        </div>
                    ),
                    () => titleAndSteps,
                    () => (
                        <div>
                            <Typography
                                size="sm"
                                weight="medium"
                                color="accent"
                                suffixIcon={ArrowRightIcon}
                                iconSlide
                                text={CUE_LABEL}
                            />
                        </div>
                    ),
                ]}
            />
        )
    }

    const items: Array<SurfaceCardPressableGroupItem> = source.map((exercise) => ({
        key: exercise.id,
        content: () => renderExerciseContent(exercise),
        // Guessed placeholder tiles never become press targets — nothing
        // underneath can act yet, and a clickable shimmer tile would be a
        // false affordance (rule 7's boundary: this is NOT a business lock).
        onPress: usingPlaceholders ? undefined : () => onSelect(exercise.id),
    }))

    // The grid is REPLACED outright by the empty message — never while
    // loading, where "empty" just means "not fetched yet" (see file header,
    // judgement on the two leaves).
    if (!isSkeleton && exercises.length === 0) {
        return (
            <div>
                <EmptyState
                    icon={TerminalWindowIcon}
                    title={EMPTY_TITLE}
                    description={EMPTY_DESCRIPTION}
                />
            </div>
        )
    }

    return (
        <div>
            <div>
                <SurfaceCardPressableGroup items={items} ariaLabel={ariaLabel} columns={{ base: 1, sm: 2 }} isSkeleton={isSkeleton} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." />
            </div>
        </div>
    )
}

export { PlaygroundExerciseGrid }

"use client"

import React, { useCallback, useState } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useParams, useRouter } from "next/navigation"
import { Button, Typography } from "@heroui/react"
import { ArrowLeftIcon, ArrowRightIcon } from "@phosphor-icons/react"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { PlaygroundRagWorkspace } from "@/components/blocks/learn/PlaygroundRagWorkspace"
import { PlaygroundHeader } from "@/components/blocks/learn/PlaygroundHeader"
import { usePlaygroundSessionContext } from "@/components/providers/PlaygroundSessionProvider"
import { pathConfig } from "@/resources/path"

/**
 * Full machine-backed RAG lab surface — the guided step column on the left
 * beside the {@link PlaygroundRagWorkspace} (import → ask → cite over the
 * learner's own local Ollama) on the right.
 *
 * The socket + session are owned by {@link usePlaygroundSessionContext} (mounted
 * at the route layout, shared with the Setup route) — this component is the
 * Lab surface only; installing Ollama and pairing the agent lives on the Setup
 * (`[slug]`) route.
 */
export const PlaygroundRagSession = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // Course from the URL, NOT the store — playgrounds are shared by every course,
    // so a stale `state.course.displayId` navigates the learner out of theirs.
    const params = useParams()
    const courseDisplayId = String(params.courseId ?? "")

    const { playground, byomState, sendRagIndex, sendRagAsk } = usePlaygroundSessionContext()

    const [currentStepIndex, setCurrentStepIndex] = useState(0)

    const steps = playground?.steps ?? []
    const currentStep = steps[currentStepIndex]

    const onPrevStep = useCallback(() => {
        setCurrentStepIndex((prev) => Math.max(0, prev - 1))
    }, [])
    const onNextStep = useCallback(() => {
        setCurrentStepIndex((prev) => Math.min(steps.length - 1, prev + 1))
    }, [steps.length])

    const onLeave = useCallback(() => {
        router.push(pathConfig().locale(locale).course(courseDisplayId).learn().playground().build())
    }, [router, locale, courseDisplayId])

    // ── lab phase — guided steps beside the RAG workspace ──
    return (
        <div className="flex h-[calc(100vh-4rem)] flex-col">
            <PlaygroundHeader step={{ current: currentStepIndex + 1, total: steps.length }} />

            <div className="grid flex-1 grid-cols-1 overflow-hidden @app-lg:grid-cols-2">
                {/* LEFT — guided step */}
                <div className="flex flex-col overflow-y-auto border-r border-default bg-background px-6 pt-5 pb-6">
                    {currentStep ? (
                        <div className="flex flex-col gap-4">
                            <Typography type="h6" weight="bold">
                                {currentStep.title}
                            </Typography>
                            <MarkdownContent markdown={currentStep.body} codeElevated />
                            {currentStep.actionHint ? (
                                <div className="rounded-medium border border-dashed border-default bg-default px-3 py-2 text-sm">
                                    <MarkdownContent markdown={currentStep.actionHint} />
                                </div>
                            ) : null}

                            <div className="flex items-center gap-2 border-t border-default pt-4">
                                <Button
                                    variant="tertiary"
                                    isDisabled={currentStepIndex === 0}
                                    onPress={onPrevStep}
                                >
                                    <ArrowLeftIcon aria-hidden focusable="false" className="size-4" />
                                    {t("playground.session.prevStep")}
                                </Button>
                                <Button
                                    variant="primary"
                                    isDisabled={currentStepIndex >= steps.length - 1}
                                    onPress={onNextStep}
                                >
                                    {t("playground.session.nextStep")}
                                    <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                                </Button>
                            </div>
                        </div>
                    ) : (
                        <AsyncContentEmpty
                            title={t("playground.session.completeTitle")}
                            description={t("playground.session.completeDescription")}
                            onRetry={onLeave}
                            retryLabel={t("playground.session.backToHub")}
                        />
                    )}
                </div>

                {/* RIGHT — machine-backed RAG workspace */}
                <div className="flex flex-col overflow-hidden bg-surface">
                    <PlaygroundRagWorkspace
                        className="h-full"
                        ragAnswer={byomState.ragAnswer}
                        ragCitations={byomState.ragCitations}
                        sendRagIndex={sendRagIndex}
                        sendRagAsk={sendRagAsk}
                    />
                </div>
            </div>
        </div>
    )
}

import React from "react"
import { LinkBack } from "@/components/atoms/navigation/Link"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `PlaygroundSetupHeader` — the identity cluster at the top of the playground Setup
 * screen: a way back to the playground hub, the exercise title, and its one-line
 * intro. Sibling of `ContentHeader` / `CourseBrief` but carries no meta cluster —
 * a playground exercise has no read state, outcomes, or counts. The single hop back
 * is a `LinkBack` placed directly in `PageHeader.breadcrumb`. One shape:
 * `isSkeleton` swaps `title`/`description` to their shimmer mirror in the same
 * slots; the back link never waits on the fetch, so it gets no skeleton.
 */

/** Props for {@link PlaygroundSetupHeader}. */
export interface PlaygroundSetupHeaderProps {
    /** Label on the back link, e.g. "Playground" — the hub this exercise was opened from. */
    breadcrumbLabel: string
    /** Fired when the back link is pressed — the caller owns the routing. */
    onBack: () => void
    /** Exercise title. */
    title: string
    /** One-line intro to the exercise. */
    description?: string
    /**
     * `true` → title/description switch to their shimmer mirror while the
     * exercise is loading. The flag flows down into the real text atoms
     * rather than a parallel skeleton tree (§12c); the back link stays live
     * (see file header).
     */
    isSkeleton?: boolean
}

/**
 * Identity cluster at the top of the playground Setup screen. See the file
 * header for the full contract.
 *
 * @param props - {@link PlaygroundSetupHeaderProps}
 */
const PlaygroundSetupHeader = ({
    breadcrumbLabel,
    onBack,
    title,
    description,
    isSkeleton = false,
}: PlaygroundSetupHeaderProps) => {
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <div className="w-fit">
                        <LinkBack label={breadcrumbLabel} onPress={onBack} />
                    </div>
                )}
                title={title}
                description={description}
            />
        </div>
    )
}

export { PlaygroundSetupHeader }

import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import type { ReactNode } from "react"
import { Tabs } from "@heroui/react"
import {
    ArrowClockwiseIcon,
    ArrowsClockwiseIcon,
} from "@phosphor-icons/react"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { TabsExtended } from "@/components/atoms/navigation/Tabs"
import { Button } from "@/components/atoms/buttons/Button"
import { Callout } from "@/components/composites/feedback/Callout"
import { ConfirmDialog } from "@/components/composites/feedback/ConfirmDialog"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV, StackH } from "@/components/frames/Stack"
import { CommandSkeleton } from "./CommandSkeleton"
import { OsTabsSkeleton } from "./OsTabsSkeleton"
import { type PlaygroundSetupOs, type PlaygroundSetupStepsProps } from "./types"

export type { PlaygroundSetupOs, PlaygroundSetupFlavor, PlaygroundSetupStepsProps } from "./types"

/**
 * BLOCK — `PlaygroundSetupSteps`: the ordered setup guide for a playground — pair
 * the local agent, install the engine (an OS-tabbed guide), and — Ollama flavor
 * only — pull the VRAM-sized models. Each step carries its own status chip,
 * why-it-matters line, runnable command(s), and re-check action.
 *
 * TWO LEAVES, ONE PER `flavor` (§14d.2 — see the component's file header for why
 * this differs from `ChallengeBrief`'s single "one leaf, N optional sections"):
 * `flavor` is chosen once per PLAYGROUND KIND, not per render, so a caller wired
 * to `"infra"` never even carries the model-readiness props the third step
 * needs — the third `SurfaceCard` is a structural fact of the ollama leaf, not a
 * data condition that could show up on the infra one.
 */

/** One `SurfaceCard` step, built by this block before render — named per §"every data shape has a name". */
interface StepEntry {
    key: string
    title: string
    status: StepStatus
    body: ReactNode
}

/** Fixed platform-wide embedding model — see file header: unlike the generation model, this never varies by device. */
const EMBEDDING_MODEL_NAME = "bge-m3"

const OS_ORDER: ReadonlyArray<PlaygroundSetupOs> = ["mac", "win", "linux"]
const OS_LABEL: Record<PlaygroundSetupOs, string> = { mac: "macOS", win: "Windows", linux: "Linux" }

/** The two-value readiness enum driving every step's trailing chip. */
type StepStatus = "ready" | "pending"

/** status → chip label/color — fixed Vietnamese copy this block owns (§14d.1), matching `PlaygroundReadinessChecklist`'s table. */
const STEP_STATUS_MAP: Record<StepStatus, EnumChipEntry> = {
    ready: { label: "Ready", color: "success" },
    pending: { label: "Not done", color: "default" },
}

/** Wraps a shell command in a fenced ```bash block for `MarkdownContent`. */
const bashBlock = (command: string): string => "```bash\n" + command + "\n```"

/**
 * The playground setup guide. See the file header for the reuse check, the
 * two-leaves-per-flavor call, and the skeleton-mirror judgement calls.
 *
 * @param props - {@link PlaygroundSetupStepsProps}
 */
const PlaygroundSetupSteps = ({
    flavor,
    engineName,
    osGuides,
    pairCommand,
    pairingCodeSecondsLeft = null,
    pairingCodeExpired = false,
    onRefreshPairingCode,
    isRefreshingPairingCode = false,
    agentReady,
    engineReady,
    genModelReady = false,
    embedModelReady = false,
    recommendedGenModel,
    deviceKnown = true,
    engineDetail,
    onVerify,
    isSkeleton = false,
}: PlaygroundSetupStepsProps) => {
    const [os, setOs] = useState<PlaygroundSetupOs>("mac")
    const [isRotateConfirmOpen, setRotateConfirmOpen] = useState(false)

    // Rotating a code nobody's agent holds yet is free; rotating a code the connected
    // agent depends on is disruptive, so THAT path confirms first (see file header).
    const onRotateClick = () => {
        if (!onRefreshPairingCode) return
        if (agentReady) {
            setRotateConfirmOpen(true)
        } else {
            onRefreshPairingCode()
        }
    }
    const onConfirmRotate = () => {
        onRefreshPairingCode?.()
        setRotateConfirmOpen(false)
    }

    // Shared by every step (see PROPS doc on `onVerify`) — built once as functions, not a
    // single JSX element re-used across positions, so each step gets its own element instance.
    const renderVerifyButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onVerify) return null
        return (
            <Button
                label="Check again"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowClockwiseIcon}
                onPress={onVerify}

            />
        )
    }
    const renderRotateButton = (): ReactNode => {
        if (isSkeleton) return <Button isSkeleton size="sm" />
        if (!onRefreshPairingCode) return null
        return (
            <Button
                label="Get new code"
                variant="tertiary"
                size="sm"
                prefixIcon={ArrowsClockwiseIcon}
                onPress={onRotateClick}
                isPending={isRefreshingPairingCode}

            />
        )
    }

    const pairingCodeNote: ReactNode = pairingCodeExpired
        ? (
            <Typography
                size="xs"
                color="danger"
                text="The pairing code has expired — get a new code to continue."

            />
        )
        : pairingCodeSecondsLeft != null
            ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`Code valid for ${pairingCodeSecondsLeft} more seconds`}

                />
            )
            : null

    const pairStepBody: ReactNode = (
        <StackV
            gap={3}
            principle="sibling-stack"
            explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="The local agent is the bridge that lets Playground control your machine — skip this step and every command in the following steps fails to run."

                    />
                ),
                () => (isSkeleton
                    ? <CommandSkeleton />
                    : <MarkdownContent source={bashBlock(pairCommand)} measure="compact" />),
                ...(!isSkeleton ? [() => pairingCodeNote] : []),
                ({ isSkeleton }: SkeletonProps) => (
                    <StackH
                        gap={3}
                        at="sm"
                        principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        isSkeleton={isSkeleton}
                        items={[
                            () => renderVerifyButton(),
                            () => renderRotateButton(),
                        ]}
                    />
                ),
            ]}
        />
    )

    const engineLabel = engineName ?? "engine"
    const osTabsRow: ReactNode = isSkeleton ? (
        <OsTabsSkeleton />
    ) : (
        <div>
            <TabsExtended
                variant="secondary"
                size="sm"
                selectedKey={os}
                onSelectionChange={(key) => setOs(key as PlaygroundSetupOs)}

            >
                <Tabs.ListContainer>
                    <Tabs.List aria-label="Choose operating system">
                        {OS_ORDER.map((key) => (
                            <Tabs.Tab key={key} id={key}>
                                <span>{OS_LABEL[key]}</span>
                                <Tabs.Indicator />
                            </Tabs.Tab>
                        ))}
                    </Tabs.List>
                </Tabs.ListContainer>
                {/* react-aria's useTab always computes an `aria-controls` id — this row shows no
                    panel content of its own (the guide below is a SEPARATE markdown render), so
                    these stay empty/`sr-only`, same convention as `Toolbar`/`Tabs` atom. */}
                {OS_ORDER.map((key) => (
                    <Tabs.Panel key={key} id={key} className="sr-only">{null}</Tabs.Panel>
                ))}
            </TabsExtended>
        </div>
    )

    const engineStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={`${engineLabel} is where the model actually runs on your machine — once installed, Playground can handle local AI tasks.`}

                    />
                ),
                () => osTabsRow,
                () => (isSkeleton
                    ? <CommandSkeleton lines={3} />
                    : <MarkdownContent source={osGuides[os]} measure="compact" />),
                ...(!isSkeleton && engineReady && engineDetail ? [() => (
                    <Callout
                        status="success"
                        title={`${engineLabel} is ready`}
                        description={engineDetail}


                    />
                )] : []),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const genModelCommand = recommendedGenModel != null ? bashBlock(`ollama pull ${recommendedGenModel}`) : null
    const embedModelCommand = bashBlock(`ollama pull ${EMBEDDING_MODEL_NAME}`)
    const modelsReady = genModelReady && embedModelReady

    const genModelSection = genModelCommand != null ? (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model sinh — ${recommendedGenModel}`}

                    />
                ),
                () => <MarkdownContent source={genModelCommand} measure="compact" />,
            ]}
        />
    ) : null

    const embedModelSection = (
        <StackV
            gap={2}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Typography
                        isSkeleton={isSkeleton}
                        size="xs"
                        color="muted"
                        text={`Model embedding — ${EMBEDDING_MODEL_NAME}`}

                    />
                ),
                () => <MarkdownContent source={embedModelCommand} measure="compact" />,
            ]}
        />
    )

    const modelsCommandsSection = (
        <StackV
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                () => genModelSection,
                () => embedModelSection,
            ]}
        />
    )

    const modelsSkeletonCommands = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => <CommandSkeleton />,
                () => <CommandSkeleton />,
            ]}
        />
    )

    const modelsStepBody: ReactNode = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                () => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text="Models need to be pulled to your machine before use — the right size for your VRAM keeps things running smoothly, without freezing or running out of memory."

                    />
                ),
                () => (isSkeleton ? (
                    modelsSkeletonCommands
                ) : deviceKnown === false ? (
                    <Callout
                        status="warning"
                        title="Device configuration not detected yet"
                        description="Finish installing the engine, then press Check again — Playground will detect your VRAM and suggest the right model size."


                    />
                ) : modelsReady ? (
                    <Callout
                        status="success"
                        title="All models are ready"
                        description="Both the text-generation model and the embedding model are already downloaded on your machine."


                    />
                ) : (
                    modelsCommandsSection
                )),
                ({ isSkeleton }: SkeletonProps) => <StackH gap={3} isSkeleton={isSkeleton} items={[() => renderVerifyButton()]} />,
            ]}
        />
    )

    const agentStatus: StepStatus = agentReady ? "ready" : "pending"
    const engineStatus: StepStatus = engineReady ? "ready" : "pending"
    const modelsStatus: StepStatus = modelsReady ? "ready" : "pending"

    const steps: Array<StepEntry> = [
        { key: "pair", title: "1. Pair local agent", status: agentStatus, body: pairStepBody },
        { key: "engine", title: `2. Install ${engineLabel}`, status: engineStatus, body: engineStepBody },
    ]
    if (flavor === "ollama") {
        steps.push({ key: "models", title: "3. Pull models for your device", status: modelsStatus, body: modelsStepBody })
    }

    // Depends on the loop variable, so it cannot be hoisted to a const above the
    // return — a small named helper instead, in the style this file already uses.
    const renderStep = (step: StepEntry) => (
        <SurfaceCard
            key={step.key}
            label={step.title}
            action={() => (
                <EnumChip
                    value={step.status}
                    map={STEP_STATUS_MAP}
                    isSkeleton={isSkeleton}

                />
            )}
            isSkeleton={isSkeleton}


            body={() => step.body}
        />
    )

    const rotateConfirm = onRefreshPairingCode ? (
        <ConfirmDialog
            isOpen={isRotateConfirmOpen}
            onOpenChange={setRotateConfirmOpen}
            title="Get a new code while the agent is connected?"
            description="The agent is currently using the old code to hold its connection — getting a new code will break the current session until you paste the new code into the agent."
            confirmLabel="Get new code"
            cancelLabel="Not now"
            onConfirm={onConfirmRotate}
            isConfirming={isRefreshingPairingCode}

        />
    ) : null

    return (
        <StackV
            identity={{ tier: "block", component: "PlaygroundSetupSteps" }}
            gap={4}
            isSkeleton={isSkeleton}
            items={[
                ...steps.map((step) => () => renderStep(step)),
                () => rotateConfirm,
            ]}
        />
    )
}

