"use client"

import React from "react"
import { Chip, cn } from "@heroui/react"
import {
    ChatCircleIcon,
    PushPinIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import type { CourseQuestionNode } from "@/modules/api/graphql/queries/types/course-questions"

/** Props for {@link QaInboxRow}. */
export interface QaInboxRowProps {
    /** The question to preview. */
    question: CourseQuestionNode
    /** Open the full conversation (expands the thread inline). */
    onOpen: () => void
}

/**
 * One collapsed row in the course-Q&A social inbox: the asker (avatar + name +
 * founder badge + relative time), a two-line preview of the question, a scope tag
 * (a static "Lesson: …" / "General" tag), an answered/unanswered status badge, the reply
 * count, and a status dot for scanning the list at a glance. The WHOLE row is a
 * single press target that opens the conversation — the lesson-funnel link lives on
 * the question bubble inside the opened thread, so the collapsed row stays a clean,
 * unambiguous button (no nested interactive controls).
 *
 * Presentational: all data arrives via props; opening is delegated to `onOpen`.
 *
 * @param props - {@link QaInboxRowProps}
 */
export const QaInboxRow = ({ question, onOpen }: QaInboxRowProps) => {
    const t = useTranslations()
    const displayName = question.author.displayName || question.author.username
    const isAnswered = question.replyCount > 0

    return (
        <div
            role="button"
            tabIndex={0}
            onClick={onOpen}
            onKeyDown={(event) => {
                if (event.key === "Enter" || event.key === " ") {
                    event.preventDefault()
                    onOpen()
                }
            }}
            className="flex w-full cursor-pointer items-start gap-3 p-3 text-left outline-none transition-colors hover:bg-default focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-accent"
        >
            <UserAvatar
                size="sm"
                username={question.author.username}
                avatar={question.author.avatar}
                seed={question.author.username}
                className="shrink-0"
            />

            <div className="flex min-w-0 flex-1 flex-col gap-1">
                {/* asker + relative time */}
                <div className="flex flex-wrap items-center gap-2 text-xs text-muted">
                    {question.isPinned ? (
                        <PushPinIcon
                            weight="fill"
                            aria-label={t("courseQa.pinned")}
                            className="size-3.5 shrink-0 text-accent-soft-foreground"
                        />
                    ) : null}
                    <span className="font-medium text-foreground">{displayName}</span>
                    {question.isFounderAuthor ? (
                        <SealCheckIcon
                            weight="fill"
                            aria-label={t("courseQa.founderBadge")}
                            className="size-3.5 shrink-0 text-accent-soft-foreground"
                        />
                    ) : null}
                    <span>· {getTimeAgoLabel(getTimeAgoMessage(question.createdAt), t)}</span>
                </div>

                {/* two-line preview */}
                <MarkdownContent
                    markdown={question.body}
                    density="compact"
                    flow="embedded"
                    previewLines={2}
                />

                {/* scope tag + status + reply count */}
                <div className="flex flex-wrap items-center gap-2">
                    <Chip size="sm" variant="soft" className="bg-default text-muted">
                        {question.contentId
                            ? t("courseQa.lessonTag", { title: question.contentTitle ?? "" })
                            : t("courseQa.generalTag")}
                    </Chip>

                    {isAnswered ? (
                        <Chip size="sm" variant="soft" color="success" className="gap-1">
                            {question.answeredByFounder ? (
                                <SealCheckIcon weight="fill" aria-hidden className="size-3.5 shrink-0" />
                            ) : null}
                            {question.answeredByFounder
                                ? t("courseQa.answeredByFounder")
                                : t("courseQa.statusAnswered")}
                        </Chip>
                    ) : (
                        <Chip size="sm" variant="soft" className="bg-default text-muted">
                            {t("courseQa.statusUnanswered")}
                        </Chip>
                    )}

                    {isAnswered ? (
                        <span className="inline-flex items-center gap-1 text-xs text-muted">
                            <ChatCircleIcon aria-hidden className="size-4" />
                            {t("courseQa.replyCount", { count: question.replyCount })}
                        </span>
                    ) : null}
                </div>
            </div>

            {/* status dot — scan the list without opening each thread */}
            <span
                aria-hidden
                className={cn(
                    "mt-2 size-2 shrink-0 rounded-full",
                    isAnswered ? "bg-success" : "bg-warning",
                )}
            />
        </div>
    )
}

import { HeartIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * BLOCK — `QaReactionBar`: the like-and-count control under a message
 * bubble. Renders one heart toggle rather than the full six-reaction picker
 * — see the component's own file header for why.
 */

/** Mirrors `QaQuestionThread`'s own `QaReactionType` (kept local — see that file's ASSUMED CONTRACTS note). */
export type QaReactionType = "like" | "love" | "haha" | "wow" | "sad" | "angry"

/** Props for {@link QaReactionBar}. */
export interface QaReactionBarProps {
    /** Total reactions on the message. */
    count: number
    /** The viewer's own reaction, or `null` if they haven't reacted. */
    myReaction: QaReactionType | null
    /** Fires with the new reaction (`"like"` to react, `null` to clear). */
    onReact: (type: QaReactionType | null) => void
    /** `true` → renders a shimmer mirror instead of the live control. */
    isSkeleton?: boolean
}

/**
 * One like-and-count toggle under a message bubble.
 *
 * @param props - {@link QaReactionBarProps}
 */
const QaReactionBar = ({
    count,
    myReaction,
    onReact,
    isSkeleton = false,
}: QaReactionBarProps) => {
    const hasReacted = myReaction != null

    if (isSkeleton) {
        return (
            <span

                className="inline-block h-5 w-10 animate-pulse rounded-full bg-default"
            />
        )
    }

    return (
        <button
            type="button"

            onClick={() => onReact(hasReacted ? null : "like")}
            aria-pressed={hasReacted}
            aria-label={hasReacted ? "Unlike" : "Like"}
            className={cn(
                // inset-exception: pill geometry, the same px-2 py-1 HeroUI ships in chip.css
                "inline-flex items-center gap-1 rounded-full px-2 py-1 transition-colors hover:bg-default",
                hasReacted && "text-danger-soft-foreground",
            )}
        >
            <HeartIcon weight={hasReacted ? "fill" : "regular"} aria-hidden focusable="false" className="size-3.5 shrink-0" />
            {count > 0 ? (
                <Typography size="xs" text={String(count)} />
            ) : null}
        </button>
    )
}

export { QaReactionBar }

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { PlayIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"

import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `QuizSetup` — choose the shape of a drill (length, seniority, name), then
 * start it. The block owns the domain wording and the lengths behind it: the
 * learner picks "quick" or "deep" and the block turns that into 5 or 10 cards,
 * saying so on the button. A run already in progress takes priority — the resume
 * strip leads the card above the form. A failed draw is reported next to the
 * button that failed.
 */

/** How long a drill runs. */
export type QuizLength = "quick" | "deep"

/** Seniority the questions aim at. */
export type QuizLevel = "junior" | "middle" | "senior" | "staff"

/** Card count per length. The BLOCK owns this — it is the judgement, not a prop. */
const LENGTH_CARDS: Record<QuizLength, number> = { quick: 5, deep: 10 }

const LENGTH_LABEL: Record<QuizLength, string> = { quick: "Quick", deep: "Deep" }

const LEVEL_LABEL: Record<QuizLevel, string> = {
    junior: "Junior",
    middle: "Middle",
    senior: "Senior",
    staff: "Staff",
}

/** A run the learner left unfinished. */
export interface QuizResumable {
    /** What the run was called when it was started. */
    name: string
    /** How many cards were answered already. */
    answered: number
    /** How many cards the run has in total. */
    total: number
    /** Fired when the learner picks the run back up. */
    onResume: () => void
}

/** Props for {@link QuizSetup}. */
export interface QuizSetupProps {
    /** Section label, localized by the caller — e.g. "Set up session". */
    label: string
    /** Current run name. */
    name: string
    /** Fired as the learner types a name. */
    onNameChange: (value: string) => void
    /** Chosen length. */
    length: QuizLength
    /** Fired when the learner picks a length. */
    onLengthChange: (length: QuizLength) => void
    /** Chosen seniority. */
    level: QuizLevel
    /** Fired when the learner picks a seniority. */
    onLevelChange: (level: QuizLevel) => void
    /** Fired when the learner starts the run. */
    onStart: () => void
    /** A run left unfinished. Present → the resume strip leads the card. */
    resumable?: QuizResumable
    /** `true` → the draw is in flight; the start button owns the busy affordance. */
    isPending?: boolean
    /** Set → the draw failed. Reported beside the action that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The drill setup form. See the file header for the full contract.
 *
 * @param props - {@link QuizSetupProps}
 */
const QuizSetup = ({
    label,
    name,
    onNameChange,
    length,
    onLengthChange,
    level,
    onLevelChange,
    onStart,
    resumable,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: QuizSetupProps) => {
    const nameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Session name" />,
                ({ isSkeleton }: SkeletonProps) => (
                    <InputText
                        value={name}
                        onValueChange={onNameChange}
                        placeholder="e.g. review Docker before the interview"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const lengthField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Length" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Session length"
                        value={length}
                        onChange={onLengthChange}

                        items={(Object.keys(LENGTH_LABEL) as Array<QuizLength>).map((key) => ({
                            value: key,
                            content: `${LENGTH_LABEL[key]} · ${LENGTH_CARDS[key]} questions`,
                        }))}
                    />
                ),
            ]}
        />
    )

    const levelField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Question level"
                        value={level}
                        onChange={onLevelChange}

                        items={(Object.keys(LEVEL_LABEL) as Array<QuizLevel>).map((key) => ({
                            value: key,
                            content: LEVEL_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const submitRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        label={`Start · ${LENGTH_CARDS[length]} questions`}
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStart}
                        isPending={isPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action that failed. At the top of the card it
    // would read as a problem with the whole form.
    const actionField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => submitRow,
            ]}
        />
    )

    const formBody = (
        <>
            {resumable != null ? (
                // A learner who left mid-run almost always means to come back. Making
                // them scroll past a start button to find their own session is how one
                // run gets abandoned twice.
                <Callout
                    title={resumable.name}
                    description={`In progress · ${resumable.answered}/${resumable.total} questions`}
                    actionLabel="Continue"
                    onAction={resumable.onResume}

                />
            ) : null}

            {nameField}
            {lengthField}
            {levelField}
            {actionField}
        </>
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => formBody]} />}
            />
        </div>
    )
}

