/** Props for {@link ParamControls}. */
export type ParamControlsProps = {
    /** Current generation params. */
    params: AiLabParamsForm
    /** Disables all inputs (e.g. while a run is in flight). */
    isDisabled?: boolean
    /** Fired with the patched params when any field changes. */
    onChange: (params: AiLabParamsForm) => void
}

/** One labelled numeric param input row. */
interface ParamFieldProps {
    /** Label shown above the input. */
    label: string
    /** DOM id for the input. */
    id: string
    /** Current numeric value. */
    value: number
    /** Smallest allowed value. */
    min: number
    /** Largest allowed value. */
    max: number
    /** Step increment. */
    step: number
    /** Disables the input. */
    isDisabled: boolean
    /** Fired with the parsed number on change. */
    onChange: (value: number) => void
}

/** A single numeric param input, styled to match the codebase's plain-input convention. */
const ParamField = ({
    label,
    id,
    value,
    min,
    max,
    step,
    isDisabled,
    onChange,
}: ParamFieldProps) => (
    <div className="flex flex-col gap-2">
        <label
            htmlFor={id}
            className="text-sm text-muted"
        >
            {label}
        </label>
        <input
            id={id}
            type="number"
            min={min}
            max={max}
            step={step}
            value={Number.isFinite(value) ? value : ""}
            disabled={isDisabled}
            onChange={(event) => onChange(Number(event.target.value))}
            className="w-full rounded-2xl border border-default bg-background px-4 py-2 text-sm text-foreground focus:border-accent focus:outline-none disabled:opacity-50"
        />
    </div>
)

/**
 * Three numeric inputs for the generation params (temperature / top-p / max tokens).
 *
 * Presentational — the parent owns the {@link AiLabParamsForm} state and receives a
 * full patched object on every change.
 * @param props - {@link ParamControlsProps}
 */
export const ParamControls = ({
    params,
    isDisabled = false,
    onChange}: ParamControlsProps) => {
    const t = useTranslations()
    return (
        <div className={"grid grid-cols-1 gap-3 @app-sm:grid-cols-3"}>
            <ParamField
                id="ai-lab-temperature"
                label={t("aiLab.playground.temperature")}
                value={params.temperature}
                min={0}
                max={2}
                step={0.1}
                isDisabled={isDisabled}
                onChange={(temperature) => onChange({ ...params, temperature })}
            />
            <ParamField
                id="ai-lab-top-p"
                label={t("aiLab.playground.topP")}
                value={params.topP}
                min={0}
                max={1}
                step={0.05}
                isDisabled={isDisabled}
                onChange={(topP) => onChange({ ...params, topP })}
            />
            <ParamField
                id="ai-lab-max-tokens"
                label={t("aiLab.playground.maxTokens")}
                value={params.maxTokens}
                min={1}
                max={32000}
                step={1}
                isDisabled={isDisabled}
                onChange={(maxTokens) => onChange({ ...params, maxTokens })}
            />
        </div>
    )
}

"use client"

import {
    TrophyIcon,
    FlameIcon,
    LightbulbIcon,
    CircleIcon,
    CircleNotchIcon,
    CheckCircleIcon,
    XCircleIcon,
    PlayIcon,
    ArrowClockwiseIcon,
    EyeIcon,
    type Icon,
} from "@phosphor-icons/react"
import React, { useMemo } from "react"
import { Button, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useParams } from "next/navigation"
import { useRouter } from "@/i18n/navigation"
import { ChallengeDifficulty } from "@/modules/types/enums/challenge-difficulty"
import { type ChallengeEntity } from "@/modules/types/entities/challenge"
import type { ChallengeProgressStatus } from "@/modules/api/graphql/queries/types/challenge-submission-progress"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { toDifficulty } from "@/modules/utils/difficulty"
import { useAppSelector } from "@/redux/hooks"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"

/** i18n key for each difficulty tier label (covers all 5 BE tiers). */
const DIFFICULTY_LABEL_KEY: Record<ChallengeDifficulty, string> = {
    [ChallengeDifficulty.Easy]: "challenge.difficulty.easy",
    [ChallengeDifficulty.Medium]: "challenge.difficulty.medium",
    [ChallengeDifficulty.Hard]: "challenge.difficulty.hard",
    [ChallengeDifficulty.Insane]: "challenge.difficulty.insane",
    [ChallengeDifficulty.Expert]: "challenge.difficulty.expert",
}

/** Status → eyebrow chip (icon + label color). */
const STATUS_META: Record<ChallengeProgressStatus, { labelKey: string; className: string; icon: Icon }> = {
    notStarted: { labelKey: "challenge.status.notStarted", className: "text-muted", icon: CircleIcon },
    inProgress: { labelKey: "challenge.status.inProgress", className: "text-warning-soft-foreground", icon: CircleNotchIcon },
    failed: { labelKey: "challenge.status.failed", className: "text-danger-soft-foreground", icon: XCircleIcon },
    completed: { labelKey: "challenge.status.completed", className: "text-success-soft-foreground", icon: CheckCircleIcon },
}

/** Status → primary action label + icon (resume semantics). */
const CTA_META: Record<ChallengeProgressStatus, { labelKey: string; icon: Icon }> = {
    notStarted: { labelKey: "challenge.cta.start", icon: FlameIcon },
    inProgress: { labelKey: "challenge.cta.continue", icon: PlayIcon },
    failed: { labelKey: "challenge.cta.retry", icon: ArrowClockwiseIcon },
    completed: { labelKey: "challenge.cta.review", icon: EyeIcon },
}

/** Props for {@link ChallengeCard}. */
export interface ChallengeCardProps {
    /** Challenge row displayed in content tab. */
    challenge: ChallengeEntity
}

/**
 * One challenge in the "Challenges" tab — a single card (bounded object): puzzle
 * eyebrow + status chip → title → difficulty/score/hint chips → clamped description
 * → footer (attempts + best score on the left, status-driven primary action on the
 * right). The card is a static surface — only the footer button navigates.
 * @param {ChallengeCardProps} props Challenge card props.
 */
export const ChallengeCard = ({ challenge}: ChallengeCardProps) => {
    const t = useTranslations()
    const router = useRouter()
    const params = useParams()
    // Per-challenge progress, populated by `useQueryChallengeSubmissionProgressSwr`.
    const completionTasks = useAppSelector((state) => state.challenge.completionTasks)
    const progress = useMemo(
        () => completionTasks.find((completionTask) => completionTask.id === challenge.id) ?? null,
        [completionTasks, challenge.id],
    )
    const status: ChallengeProgressStatus = progress?.status ?? "notStarted"
    const statusMeta = STATUS_META[status]
    const ctaMeta = CTA_META[status]
    const StatusIcon = statusMeta.icon
    const CtaIcon = ctaMeta.icon

    // Footer-left progress line: attempts + best score, or "not attempted yet".
    const maxScore = progress?.maxScore ?? challenge.score
    const attemptsLine = useMemo(() => {
        const attempts = progress?.numAttempts ?? 0
        if (attempts <= 0) {
            return t("challenge.attempts.none")
        }
        const base = t("challenge.attempts.some", { count: attempts })
        if (progress?.lastScore == null) {
            return base
        }
        return `${base} · ${t("challenge.attempts.bestScore", { score: progress.lastScore, maxScore })}`
    }, [progress?.numAttempts, progress?.lastScore, maxScore, t])

    const openChallenge = () => {
        const courseId = params.courseId as string
        const moduleId = params.moduleId as string
        const contentId = params.contentId as string
        router.push(`/courses/${courseId}/learn/content/modules/${moduleId}/contents/${contentId}/challenges/${challenge.id}`)
    }

    return (
        // each challenge is its OWN distinct card (surface fill + border on a plain div so
        // the utilities aren't overridden by HeroUI Card's unlayered styles). The card itself
        // is static (NOT clickable, no hover/cursor) — only the footer "Do" button navigates.
        // Completed rows are de-emphasized.
        <div className={cn("rounded-3xl border border-default bg-surface p-4", status === "completed" && "opacity-80")}>
            <div className="flex flex-col gap-3">
                <div>
                    <div className="flex items-center justify-between gap-2 mb-2">
                        {/* quiet eyebrow — the challenge number is a low-key label, not a heading;
                            the title below is the meaningful line. No motif icon (it lives once on
                            the section's LabeledCard label). */}
                        <span className="text-xs text-muted">
                            {t("challenge.number", { index: challenge.sortIndex })}
                        </span>
                        <span className={cn("inline-flex items-center gap-2 text-xs", statusMeta.className)}>
                            <StatusIcon className="size-4 shrink-0" />
                            {t(statusMeta.labelKey)}
                        </span>
                    </div>
                    <div className="font-medium">{challenge.title}</div>
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                    {/* the difficulty ramp lives in ONE place (`DifficultyChip`); this row used to
                        tint a generic chip from a second, raw-Tailwind palette of its own */}
                    <DifficultyChip
                        difficulty={toDifficulty(challenge.difficulty)}
                        label={t(DIFFICULTY_LABEL_KEY[challenge.difficulty] ?? "challenge.difficulty.easy")}
                    />
                    <span className="inline-flex items-center gap-1 text-xs text-muted">
                        <TrophyIcon className="size-4 shrink-0" />
                        {challenge.score}
                    </span>
                    {challenge.hint ? (
                        <span className="inline-flex items-center gap-1 text-xs text-muted">
                            <LightbulbIcon className="size-4 shrink-0" />
                            {t("challenge.hintTag")}
                        </span>
                    ) : null}
                </div>
                {challenge.description ? (
                    <MarkdownContent
                        markdown={challenge.description}
                        density="caption"
                        tone="muted"
                        flow="embedded"
                        previewLines={2}
                    />
                ) : null}
                <div className="flex items-center justify-between gap-2">
                    <span className="inline-flex items-center gap-2 text-xs text-muted">
                        <ArrowClockwiseIcon className="size-4 shrink-0" />
                        {attemptsLine}
                    </span>
                    <Button onPress={openChallenge}>
                        <CtaIcon className="size-5" />
                        {t(ctaMeta.labelKey)}
                    </Button>
                </div>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
