                                <Tabs.Tab key={option.id} id={option.id}>
                                    {option.label}
                                    <Tabs.Indicator />
                                </Tabs.Tab>
                            ))}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </Tabs>
                <Typography type="body-sm" color="muted">
                    {t("finalProject.page.submitGithub.langFieldHint")}
                </Typography>
            </div>
