                    />
                </TextField>
                <Typography type="body-sm" color="muted">
                    {t("finalProject.page.submitGithub.privateTokenHint")}
                </Typography>
                <div className="flex flex-wrap items-center gap-2">
                    <Button
                        variant="secondary"
                        isPending={isSavingToken}
                        isDisabled={isSavingToken || tokenInput.trim().length === 0}
                        onPress={() => {
                            void saveGithubToken(tokenInput).then(() => setTokenInput(""))
                        }}
                    >
                        {({ isPending }) => (
                            <>
                                {isPending ? <Spinner size="sm" color="current" /> : null}
                                {t("finalProject.page.submitGithub.privateTokenSaveButton")}
                            </>
                        )}
                    </Button>
                    <Button
                        variant="tertiary"
                        isDisabled={isSavingToken}
                        onPress={() => {
                            void clearGithubToken().then(() => setTokenInput(""))
                        }}
                    >
                        {t("finalProject.page.submitGithub.privateTokenRemoveButton")}
                    </Button>
                </div>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { PlayIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { ContinueCard } from "@/components/blocks/cards/ContinueCard"
import { SurfaceCardHeader } from "@/components/composites/cards/SurfaceCard/surface-card-header"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Grid } from "@/components/frames/Grid"
import { StackV } from "@/components/frames/Stack"

/** Course slugs that have a dedicated capstone teaser (`finalProject.gatePreview.<key>`). */
type CourseSlug = "fullstack-mastery" | "system-design-mastery" | "devops-mastery"

const DEFAULT_COURSE: CourseSlug = "fullstack-mastery"

const isCourseSlug = (value: string | undefined): value is CourseSlug =>
    value === "fullstack-mastery" || value === "system-design-mastery" || value === "devops-mastery"

/** `state.course.displayId` slug → i18n key segment under `finalProject.gatePreview`. */
const COURSE_I18N_KEY: Record<CourseSlug, string> = {
    "fullstack-mastery": "fullstackMastery",
    "system-design-mastery": "systemDesignMastery",
    "devops-mastery": "devopsMastery",
}

/**
 * Non-interactive MOCK teaser of the Personal Project (capstone) surface — mirrors
 * {@link import("../PersonalProjectDashboard").PersonalProjectDashboard}'s block
 * layout (hero {@link ContinueCard} + {@link ProgressMeter} + item grid under a
 * {@link SurfaceCardHeader}) using the REAL milestone-0 task titles of the active course
 * (`state.course.displayId`, not fabricated copy), fed to
 * {@link import("../../shared/EnrollGate").EnrollGate} as its `preview` so a trial
 * viewer sees the actual hands-on work behind the faded enroll card. Decorative only
 * (`aria-hidden` applied by the gate) — no state, no interactivity.
 */
export const PersonalProjectGatePreview = () => {
    const t = useTranslations()
    const courseSlug = useAppSelector((state) => state.course.displayId)
    const course = isCourseSlug(courseSlug) ? courseSlug : DEFAULT_COURSE
    const key = COURSE_I18N_KEY[course]
    const taskMeta = t("finalProject.gatePreview.taskMeta")

    return (
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-6">
            <div className="flex flex-col gap-3">
                <ContinueCard
                    variant="hero"
                    icon={() => <PlayIcon weight="fill" />}
                    title={t(`finalProject.gatePreview.${key}.heroTitle`)}
                    subtitle={taskMeta}
                    ctaLabel={t("finalProject.dashboard.continue")}
                />
                <ProgressMeter
                    value={0}
                    max={3}
                    label={t("finalProject.dashboard.completion")}
                    showValue
                />
            </div>
            {/* B37 Decision E: ContinueCard tiles self-frame — StackV label-field
                replaces LabeledCard frameless around the grid. */}
            <StackV
                gap={3}
                principle="label-field"
                explain="Section label above its control is label-field — not title-subtitle (no paired title/supporting lines), not name-handle, not icon-text; the label names the surface the way a field label names its control."
                items={[
                    () => <SurfaceCardHeader label={t(`finalProject.gatePreview.${key}.milestone`)} />,
                    () => (
                        <Grid
                            columns={{ base: 1, sm: 2 }}
                            principle="sibling-stack"
                            explain="Gate-preview task tiles share one section grid — not block-boundary."
                            items={[
                                {
                                    key: "item1",
                                    content: () => (
                                        <ContinueCard
                                            variant="item"
                                            title={t(`finalProject.gatePreview.${key}.item1Title`)}
                                            subtitle={taskMeta}
                                            ctaLabel={t("finalProject.dashboard.continue")}
                                        />
                                    ),
                                },
                                {
                                    key: "item2",
                                    content: () => (
                                        <ContinueCard
                                            variant="item"
                                            title={t(`finalProject.gatePreview.${key}.item2Title`)}
                                            subtitle={taskMeta}
                                            ctaLabel={t("finalProject.dashboard.continue")}
                                        />
                                    ),
                                },
                            ]}
                        />
                    ),
                ]}
            />
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import {
    Chip,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import _ from "lodash"
import { ListChecksIcon } from "@phosphor-icons/react"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { useAppSelector } from "@/redux/hooks"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { Box } from "@/components/frames/Box"

/** Props for {@link TaskCriteriaList}. */
export type TaskCriteriaListProps = Record<string, never>
/**
 * Accordion list of pass criteria with score chips and markdown hints.
 *
 * Self-contained: reads sorted criteria from the redux task state, no props needed.
 * @param props - optional className for the root element
 */
export const TaskCriteriaList = () => {
    const t = useTranslations()
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [selectedTaskId, selectedTaskDetail, milestoneEntities])

    const sortedCriterias = useMemo(() => {
        if (!displayTask?.criterias) return []
        return _.cloneDeep(displayTask.criterias)
            .sort((prev, next) => prev.sortIndex - next.sortIndex)
    }, [displayTask?.criterias])

    if (sortedCriterias.length === 0) {
        // section sits under the visible "task.criteriaTitle" label, so an empty
        // list needs a proper empty-state instead of a silent null (self-hide is
        // only for un-labeled widgets)
        return (
            <Box>
                <EmptyState
                    icon={ListChecksIcon}
                    title={t("task.criteriaEmpty")}
                />
            </Box>
        )
    }

    return (
        // NO `label`: the parent already renders the "task.criteriaTitle" heading
        // above this list — a label here would be label-on-label (accordion.md §3d).
        // The per-criterion score rides in the header via `titleEnd`.
        <LabeledAccordionCard
            allowsMultipleExpanded
            items={sortedCriterias.map((criteria, index) => ({
                id: criteria.id,
                title: `${index + 1}. ${criteria.text}`,
                titleEnd: () => (
                    <Chip size="sm" variant="secondary" color="accent">
                        {t("task.criteriaScore", { score: criteria.score })}
                    </Chip>
                ),
                body: () => criteria.hint ? (
                    <MarkdownContent markdown={criteria.hint} />
                ) : (
                    <div className="text-sm text-muted italic">
                        {t("task.criteriaNoHint")}
                    </div>
                ),
            }))}
        />
    )
}

"use client"

import React, { useMemo } from "react"
import {
    useTranslations,
} from "next-intl"
import {
    TaskResultsSkeleton,
} from "../TaskResultsSkeleton"
import { Score } from "@/components/blocks/stats/Score"
import { StarCiAIBadge } from "@/components/blocks/learn/StarCiAIBadge"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { useQueryUserPersonalTaskAttemptsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserPersonalTaskAttemptsSwr"

/**
 * Grading results block: AI badge, score, and short feedback.
 *
 * Self-contained: reads the latest attempt from its own SWR query. First load
 * shimmers in place; settled with no attempt at all, the block self-hides rather
 * than showing an empty card nobody asked for.
 */
export const TaskResults = () => {
    const t = useTranslations()
    const attemptsSwr = useQueryUserPersonalTaskAttemptsSwr()

    const attemptRows = useMemo(
        () => attemptsSwr.data?.data ?? [],
        [attemptsSwr.data?.data],
    )
    const latestAttempt = attemptRows[0]

    const shortFeedback = useMemo(() => {
        const raw = latestAttempt?.shortFeedback?.trim() ?? ""
        return raw || t("finalProject.page.attemptsDrawer.feedbackEmpty")
    }, [latestAttempt?.shortFeedback, t])

    if (attemptsSwr.isLoading) {
        return <TaskResultsSkeleton />
    }
    if (!latestAttempt) {
        return null
    }

    return (
        <SurfaceCard
            identity={{ tier: "block", component: "TaskResults" }}
            label={t("task.resultsTitle")}
            action={() => <StarCiAIBadge />}
            body={() => (
                <StackV
                    gap={4}
                    items={[
                        () => <Score current={latestAttempt.score ?? 0} max={20} />,
                        () => <Typography size="sm" color="muted" text={shortFeedback} />,
                    ]}
                />
            )}
        />
    )
}

"use client"

import React, { useState } from "react"
import { Drawer } from "@heroui/react"
import { CaretRightIcon, GearSixIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import {
    PersonalProjectSubmission,
} from "../PersonalProjectSubmission"
import {
    GithubGradingSettings,
} from "../GithubGradingSettings"
import {
    TaskActions,
} from "../TaskActions"
import {
    TaskResults,
} from "../TaskResults"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { usePersonalProjectGithubStore } from "@/hooks/zustand/personalProjectGithub/store"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link TaskSubmissionPanel}. */
export type TaskSubmissionPanelProps = Record<string, never>
/**
 * The persistent submission panel — the RIGHT, sticky side of the split workspace.
 *
 * Progressive disclosure: the panel keeps only the primary loop — the GitHub repo URL
 * ({@link PersonalProjectSubmission}), the evaluate/feedback actions ({@link TaskActions}), and the
 * latest grading result ({@link TaskResults}). The set-once config (grading language, branch,
 * private-repo token) is moved into a settings Drawer ({@link GithubGradingSettings}), opened from a
 * read-only summary row. The submission is per-project (not per-task), so this panel does NOT gate
 * on the selected task — only the left brief column swaps per task.
 * @param props - optional className for the root element
 */
export const TaskSubmissionPanel = () => {
    const t = useTranslations()
    const [isSettingsOpen, setSettingsOpen] = useState(false)
    // read-only summary of the current grading config (what the Drawer edits)
    const lang = usePersonalProjectGithubStore((state) => state.lang)
    const branch = usePersonalProjectGithubStore((state) => state.branch)
    const langLabelMap: Record<string, string> = {
        typescript: t("programmingLanguage.typescript"),
        java: t("programmingLanguage.java"),
        csharp: t("programmingLanguage.csharp"),
        go: t("programmingLanguage.go"),
    }

    return (
        <div className={"flex flex-col gap-6"}>
            <SurfaceCard
                label={t("finalProject.page.submitGithub.title")}
                body={() => (
                    <StackV
                        principle="block-boundary"
                        explain="Github config group and submit CTA are separate sections in the submit panel — not sibling-stack, because the CTA is a distinct action block."
                        items={[
                            () => (
                                <div className="flex flex-col gap-3">
                                    <PersonalProjectSubmission />
                                    <button
                                        type="button"
                                        onClick={() => setSettingsOpen(true)}
                                        aria-label={t("finalProject.page.submitGithub.settingsTitle")}
                                        aria-expanded={isSettingsOpen}
                                        className="group flex cursor-pointer items-center justify-between gap-3 rounded-medium bg-default-100 px-3 py-2 text-left outline-none focus-visible:ring-2 focus-visible:ring-accent"
                                    >
                                        <span className="flex items-center gap-2 text-sm">
                                            <GearSixIcon className="size-4 shrink-0" />
                                            <span className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">{t("finalProject.page.submitGithub.settingsTitle")}</span>
                                        </span>
                                        <span className="flex min-w-0 items-center gap-2 text-xs text-muted">
                                            <span className="truncate">{(langLabelMap[lang] ?? lang)} · {branch}</span>
                                            <CaretRightIcon weight="bold" className="size-4 shrink-0" />
                                        </span>
                                    </button>
                                </div>
                            ),
                            () => <TaskActions />,
                        ]}
                    />
                )}
            />
            <TaskResults />

            {/* grading-settings Drawer (set-once config: language / branch / token) */}
            <Drawer>
                <Drawer.Backdrop isOpen={isSettingsOpen} onOpenChange={setSettingsOpen} className="backdrop-blur-sm">
                    <Drawer.Content placement="right">
                        <Drawer.Dialog className="p-0">
                            <div className="p-3">
                                <Drawer.CloseTrigger />
                                <Drawer.Header>
                                    <Drawer.Heading>{t("finalProject.page.submitGithub.settingsTitle")}</Drawer.Heading>
                                </Drawer.Header>
                            </div>
                            <div className="border-b" />
                            <Drawer.Body className="p-6 pt-3">
                                <GithubGradingSettings />
                            </Drawer.Body>
                        </Drawer.Dialog>
                    </Drawer.Content>
                </Drawer.Backdrop>
            </Drawer>
        </div>
    )
}
